// ================= Aprender: módulo «mercados» =================
// Regras de Portugal só com fonte oficial (campo `src`); o que não ficou confirmado leva `pending:true` («Por confirmar»).

// Contas partilhadas pelos temas deste módulo (prefixo _mer_ para não colidir com outros ficheiros).
const _mer_pt=(x,d)=>Number(x).toLocaleString('pt-PT',{minimumFractionDigits:d,maximumFractionDigits:d});
const _mer_eu=n=>Number(n).toLocaleString('pt-PT',{style:'currency',currency:'EUR',maximumFractionDigits:0,useGrouping:'always'});
const _mer_e2=n=>Number(n).toLocaleString('pt-PT',{style:'currency',currency:'EUR',useGrouping:'always'});
// Preço de uma obrigação sem cupão (valor de 100 no vencimento) para uma taxa anual em % e um prazo em anos.
const _mer_zc=(taxa,anos)=>100/Math.pow(1+taxa/100,anos);
// Livro de ordens de exemplo (tema «O que é a bolsa e como se formam os preços»): preço e quantidade.
const _mer_bids=[[9.98,500],[9.97,1200],[9.95,800]], _mer_asks=[[10.00,400],[10.01,900],[10.03,1500]];
// Preço médio de uma compra «a mercado» de `qtd` ações, a consumir as vendas do livro por ordem.
const _mer_buy=qtd=>{ let falta=qtd,custo=0; for(const [p,q] of _mer_asks){ const t=Math.min(falta,q); custo+=t*p; falta-=t; if(!falta) break; } return custo/qtd; };

// Leilão de abertura de exemplo (tema «A bolsa por dentro»): ordens com limite de preço, por preço.
const _mer_leilao=(()=>{ const buy={10.2:300,10.1:400,10.0:500,9.9:400,9.8:300}, sell={9.8:200,9.9:300,10.0:400,10.1:500,10.2:400};
  return [9.8,9.9,10.0,10.1,10.2].map(p=>{ let d=0,s=0; for(const k in buy) if(+k>=p-1e-9) d+=buy[k]; for(const k in sell) if(+k<=p+1e-9) s+=sell[k]; return {p,d,s,v:Math.min(d,s)}; }); })();
const _mer_leilaoBest=_mer_leilao.reduce((a,b)=>b.v>a.v?b:a), _mer_leilaoP=_mer_leilaoBest.p, _mer_leilaoV=_mer_leilaoBest.v;

// Mini-índice de exemplo (tema «Índices»): valor de mercado em milhões e variação no ano, em %.
const _mer_idx=(()=>{ const e=[{n:'A',m:600,v:10},{n:'B',m:300,v:0},{n:'C',m:100,v:-20}], t=e.reduce((s,x)=>s+x.m,0);
  e.forEach(x=>{ x.wm=x.m/t; x.we=1/e.length; });
  return {rows:e,cap:e.reduce((s,x)=>s+x.wm*x.v,0),igual:e.reduce((s,x)=>s+x.we*x.v,0)}; })();

// Índice de difusão estilo PMI: % «melhor» + metade da % «igual».
const _mer_pmi=(melhor,igual)=>melhor+0.5*igual;
// Curvas de exemplo (tema «Curva de rendimentos»): rendimento por prazo para cada forma, em %.
const _mer_curvas=(()=>{ const rows=[{n:'3 meses',v:[2.00,3.10,4.00]},{n:'2 anos',v:[2.40,3.00,3.60]},{n:'5 anos',v:[2.80,3.05,3.35]},{n:'10 anos',v:[3.10,3.10,3.20]},{n:'30 anos',v:[3.50,3.20,3.30]}];
  return {rows,dif:[0,1,2].map(i=>rows[3].v[i]-rows[1].v[i])}; })();

LRN.push(
{ id:'bolsa-precos', topic:'mercados', o:1, title:'O que é a bolsa e como se formam os preços', mins:7,
  lead:'A bolsa é um mercado organizado onde compradores e vendedores se encontram. O preço de uma ação não é fixado por ninguém: sai do equilíbrio entre quem quer comprar e quem quer vender, a cada instante.',
  blocks:[
    {t:'h',id:'h0',x:'Uma imagem: a lota do peixe'},
    {t:'p',id:'p0',x:'Numa lota, os pescadores chegam com o peixe e os compradores fazem ofertas. Ninguém fixou antes o preço da sardinha: depende de quanto peixe há e de quantos querem comprar. Quando há pouco peixe e muita gente, o preço sobe; quando há barcos a mais, desce. A bolsa funciona assim, mas com ações, e com milhares de pessoas e programas a fazer ofertas ao mesmo tempo.'},
    {t:'p',id:'p1',x:'Uma <b>ação</b> é uma pequena parte de uma empresa. Quem a compra torna-se sócio dessa parte e participa nos lucros (dividendos) e na valorização, mas também nos riscos. As empresas cotadas em bolsa podem ser compradas e vendidas todos os dias úteis.'},
    {t:'p',id:'p1b',x:'Há dois momentos diferentes. No <b>mercado primário</b>, a empresa vende ações novas aos investidores para arrecadar dinheiro (por exemplo, quando entra em bolsa pela primeira vez, numa «oferta pública inicial» ou IPO). No <b>mercado secundário</b>, que é o que se vê todos os dias, os investidores compram e vendem entre si ações que já existem: a empresa não recebe nada com estas trocas, o dinheiro passa de um investidor para outro.'},
    {t:'h',id:'h1',x:'Compradores, vendedores e o livro de ordens'},
    {t:'p',id:'p2',x:'Cada ordem de compra indica um preço máximo (<b>bid</b>) e cada ordem de venda um preço mínimo (<b>ask</b>). O negócio faz-se quando os dois se cruzam. A diferença entre o melhor ask e o melhor bid é o <b>spread</b>. O «preço» que vês é o do <b>último negócio</b>.'},
    {t:'p',id:'p2b',x:'O conjunto das ordens à espera chama-se <b>livro de ordens</b>. Eis um exemplo inventado, para uma ação a ser negociada à volta de 10 €:'},
    {t:'cmp',id:'c1',head:['Ordens de compra (bid)','Quantidade','Ordens de venda (ask)','Quantidade'],rows:[0,1,2].map(i=>[_mer_e2(_mer_bids[i][0]),String(_mer_bids[i][1]),_mer_e2(_mer_asks[i][0]),String(_mer_asks[i][1])]),cap:'Exemplo inventado. O melhor preço de compra é 9,98 € e o melhor de venda é 10,00 €: o spread é de '+_mer_e2(_mer_asks[0][0]-_mer_bids[0][0])+' (cerca de '+_mer_pt((_mer_asks[0][0]-_mer_bids[0][0])/_mer_asks[0][0]*100,2)+'%).'},
    {t:'p',id:'p2c',x:`Se decidires comprar 600 ações «a mercado» (ao melhor preço disponível, agora), primeiro consomes as 400 à venda a 10,00 € e depois as restantes 200 a 10,01 €. O preço médio pago é ${_mer_e2(_mer_buy(600))}, ligeiramente acima do «preço» de 10,00 € que viste. A diferença parece pequena, mas em ações pouco negociadas, ou com ordens grandes, pode ser grande. Para te protegeres, usa ordens com <b>limite de preço</b> (tema «Tipos de ordem»).`},
    {t:'fazve',id:'q1',ensina:['p2b','c1','p2c'],q:'Com o livro de ordens acima, queres comprar 600 ações a mercado. Qual é, aproximadamente, o preço médio que pagas por ação?',unit:'€',answer:_mer_buy(600),tol:.002,why:`(400 × 10,00 + 200 × 10,01) ÷ 600 ≈ ${_mer_e2(_mer_buy(600))}. Pagaste um pouco mais do que o melhor preço de venda porque a ordem era maior do que a quantidade disponível a esse preço.`},
    {t:'h',id:'h2',x:'O que faz o preço mexer'},
    {t:'p',id:'p3',x:'Se aparecem de repente mais compradores do que vendedores, quem quer comprar aceita pagar mais para ser atendido, e o preço <b>sobe</b>. Se há mais vendedores, o preço <b>desce</b>. As notícias sobre lucros, taxas de juro ou o ambiente político mudam o que as pessoas estão dispostas a pagar, e é por isso que os preços se mexem.'},
    {t:'decide',id:'q2',ensina:['p3'],label:'Decide',q:'Numa ação, de repente muitas pessoas querem comprar e quase ninguém quer vender. O que tende a acontecer ao preço?',o:['Desce, porque há muita atividade','Fica igual, porque o preço é fixo','Sobe, porque os compradores aceitam pagar mais para ser atendidos'],c:2,why:'Há mais procura do que oferta ao preço atual, por isso quem compra tem de oferecer mais. O preço sobe até que haja equilíbrio.'},
    {t:'p',id:'p3b',x:'O preço de uma ação reflete, sobretudo, <b>expectativas</b>: o que os investidores esperam que a empresa lucre no futuro, ajustado ao risco e às taxas de juro. Por isso um bom resultado já «previsto» pode não fazer o preço subir, e um resultado ligeiramente melhor do que o esperado pode fazê-lo subir muito. O que move o preço é a surpresa, não só a notícia.'},
    {t:'h',id:'h3',x:'Preço, valor e capitalização'},
    {t:'p',id:'p4',x:`O preço por ação não diz se uma empresa é grande ou pequena. Uma empresa com 2 milhões de ações a 15 € vale na bolsa ${_mer_eu(2e6*15)}, a sua <b>capitalização bolsista</b> (preço × número de ações). Outra, com 10 milhões de ações a 5 €, vale ${_mer_eu(10e6*5)}, quase o dobro, apesar de cada ação custar menos. Por isso «ação barata» por ter preço baixo não quer dizer nada.`},
    {t:'note',id:'n1',x:'Preço baixo não é o mesmo que «barato». O preço mede quanto o mercado paga hoje, não quanto a empresa vale. Esse é o tema da análise fundamental.'},
    {t:'fazve',id:'q3',ensina:['p4'],q:'Uma empresa tem 4 milhões de ações e cada uma custa 12 €. Qual é a capitalização bolsista?',unit:'€',answer:4e6*12,tol:.001,why:`4 000 000 × 12 € = ${_mer_eu(4e6*12)}. A capitalização é o preço de todas as ações juntas, não o preço de uma só.`},
    {t:'h',id:'h4',x:'Um caso real: a bolha das empresas da internet'},
    {t:'p',id:'p5',x:'No fim dos anos 90, muitas empresas ligadas à internet viram os preços das ações subirem enormemente, mesmo sem lucros, só porque os investidores esperavam que o negócio fosse gigante. Os preços refletiam expectativas, não resultados. Em 2000 as expectativas ajustaram-se e as ações cotadas nesse segmento caíram violentamente; muitas empresas desapareceram e as que sobreviveram demoraram mais de uma década a recuperar os máximos. A lição é que o preço pode afastar-se muito do valor durante bastante tempo, e voltar.'},
    {t:'h',id:'h5',x:'Os erros que mais custam'},
    {t:'ul',id:'u1',x:[
      'Achar que uma ação com preço baixo é «barata» e uma com preço alto é «cara».',
      'Olhar só para o último preço e ignorar o spread e a quantidade disponível, sobretudo em ações pouco negociadas.',
      'Dar ordens a mercado em momentos de grande oscilação, como à abertura ou depois de uma notícia.',
      'Comprar porque «está a subir» e vender porque «está a descer», sem perceber o que mudou.',
      'Pensar que o preço «tem de» voltar a um valor anterior: o mercado não deve nada a ninguém.']},
    {t:'erro',id:'q4',ensina:['p1','p2','p4'],label:'Encontra o erro',q:'Uma destas frases sobre a bolsa está errada. Qual?',o:['Uma ação é uma parte de uma empresa','O preço sai das ordens de quem compra e de quem vende','O spread é a diferença entre o melhor preço de venda e o melhor de compra','O preço de uma ação é fixado todos os dias por uma entidade central'],c:3,why:'Ninguém fixa o preço: forma-se no cruzamento das ordens de compra e de venda.'},
    {t:'h',id:'h6',x:'Em Portugal'},
    {t:'p',id:'p6',x:'A bolsa portuguesa é a Euronext Lisboa, parte do grupo Euronext (tema «A bolsa por dentro: Euronext, market makers, liquidação e custódia»). Os horários de negociação e a forma como se dão as ordens estão nos temas «Horários da Euronext Lisboa» e «Tipos de ordem». Ao vender ações com ganho, pagas imposto sobre as mais-valias (tema «Mais-valias: quanto imposto pagas ao vender»), e a corretora cobra comissões (tema «Comissões e imposto do selo»).'},
    {t:'h',id:'h7',x:'Em poucas palavras'},
    {t:'ul',id:'u2',x:[
      'A bolsa é um mercado organizado: o preço forma-se no cruzamento das ordens de compra e de venda, sem preço fixado por ninguém.',
      'Bid é o preço máximo de quem compra; ask é o preço mínimo de quem vende; spread é a diferença entre os dois.',
      'Uma ordem grande a mercado pode ser executada a vários preços: o preço médio fica acima do melhor preço de venda.',
      'O preço reflete expectativas: o que move o mercado é a surpresa.',
      'Preço baixo não é barato. A capitalização (preço × nº de ações) é que mede o tamanho da empresa.']}
  ], src:[{l:'Euronext',u:'https://www.euronext.com'}] }
,
{ id:'bolsa-por-dentro', topic:'mercados', o:2, title:'A bolsa por dentro: Euronext, market makers, liquidação e custódia', mins:8,
  lead:'Quando carregas em «comprar», o que acontece entre o teu telemóvel e as ações aparecerem na tua conta? Há uma cadeia de empresas e de regras por trás: a corretora, a bolsa, quem garante que o negócio se cumpre e quem guarda as ações. Perceber esta cadeia ajuda a perceber custos, riscos e porque é que o dinheiro às vezes demora a aparecer.'
  ,blocks:[
    {t:'h',id:'h0',x:'A viagem de uma encomenda'},
    {t:'p',id:'p0',x:'Pensa numa encomenda online. Fazes o pedido, a loja confirma, a transportadora recolhe, alguém garante que o pagamento é feito e o produto chega a casa. Comprar ações é parecido: entre o clique e o registo das ações em teu nome há vários intermediários, cada um com um papel. Na maior parte dos dias, tudo corre sem que dês por nada, e é por isso mesmo que convém saber quem faz o quê.'},
    {t:'h',id:'h1',x:'Passo a passo'},
    {t:'ul',id:'u1',x:[
      '<b>Ordem</b>: dás a ordem de compra ou venda à tua corretora ou banco, que a envia para a bolsa.',
      '<b>Negociação</b>: a bolsa (em Portugal, a Euronext Lisboa) junta as ordens num livro de ordens e um motor de cruzamento emparelha compras e vendas. A regra de prioridade habitual é <b>preço primeiro, depois o momento em que chegou</b>: a ordem com melhor preço passa à frente, e entre preços iguais, a mais antiga.',
      '<b>Compensação (clearing)</b>: depois do negócio, uma entidade chamada contraparte central (CCP) coloca-se entre comprador e vendedor e garante que ambos cumprem. Se um deles falhar, é a CCP que assume o problema, não o outro investidor.',
      '<b>Liquidação (settlement)</b>: é o momento em que as ações mudam de dono e o dinheiro muda de mão. Hoje, nos mercados da União Europeia, isto acontece <b>dois dias úteis depois</b> do negócio, o chamado T+2.',
      '<b>Custódia</b>: as ações ficam registadas em conta de valores mobiliários, mantida por um intermediário (a corretora ou o banco), e no registo central de títulos, onde fica a prova de que és o titular.']},
    {t:'p',id:'p1',x:'Até à liquidação, o negócio já está fechado (o preço está fixado), mas a troca ainda não foi concluída. Na prática, o preço do negócio não muda; o que muda é o momento em que o dinheiro sai e as ações entram. Por isso, em dias de feriado a liquidação pode atrasar-se, e por isso o dinheiro de uma venda pode não estar disponível para levantar no próprio dia.'},
    {t:'h',id:'h2',x:'Como se forma o preço à abertura e ao fecho'},
    {t:'p',id:'p2',x:'Durante o dia, as ordens cruzam-se continuamente. Mas a abertura e o fecho costumam ser feitos por <b>leilão</b>: durante uns minutos juntam-se ordens sem negociar, e no fim calcula-se um único preço, aquele em que <b>mais ações mudam de mãos</b>. Vê um exemplo inventado:'},
    {t:'cmp',id:'c1',head:['Preço','Quem quer comprar a este preço ou mais (quantidade acumulada)','Quem quer vender a este preço ou menos (quantidade acumulada)','Ações trocadas'],rows:_mer_leilao.map(r=>[_mer_e2(r.p),String(r.d),String(r.s),String(r.v)]),cap:'Exemplo inventado. O preço de leilão é o que maximiza as ações trocadas: '+_mer_e2(_mer_leilaoP)+' ('+_mer_leilaoV+' ações).'},
    {t:'fazve',id:'q1',ensina:['p2','c1'],q:'Pela tabela do leilão, a que preço (em euros) se negoceiam mais ações?',unit:'€',answer:_mer_leilaoP,tol:.005,why:`A ${_mer_e2(_mer_leilaoP)} trocam-se ${_mer_leilaoV} ações, mais do que a qualquer outro preço. A procura acumulada (quem compra a este preço ou mais) e a oferta acumulada (quem vende a este preço ou menos) emparelham-se nesse ponto.`},
    {t:'h',id:'h3',x:'Market makers: quem está sempre do outro lado'},
    {t:'p',id:'p3',x:'Para haver sempre preço, alguém tem de estar disposto a comprar e a vender a qualquer momento. É o papel dos <b>market makers</b> (também chamados animadores de mercado ou fornecedores de liquidez). Colocam ordens de compra e de venda em simultâneo, com um pequeno spread entre elas, e ganham essa diferença quando as ordens se cruzam. Em troca de ganharem o spread, correm o risco de ficar com ações que entretanto descem.'},
    {t:'p',id:'p3b',x:`Para ter uma ideia do que o spread representa, se um market maker comprar a 9,98 € e vender a 10,00 € (como no livro do tema «O que é a bolsa e como se formam os preços»), ganha ${_mer_e2(0.02)} por ação. Repetido mil vezes ao longo de um dia, são ${_mer_e2(0.02*1000)} (valores de exemplo, sem contar custos nem risco). Para ti, o spread é um custo escondido, mas é também o preço de teres sempre alguém para te comprar ou vender. Ações e ETFs muito negociados têm spreads pequenos; os pouco negociados têm spreads grandes.`},
    {t:'cmp',id:'c2',head:['Quem','O que faz','O que ganha'],rows:[
      ['Investidor','Compra e vende para os seus objetivos','Valorização e dividendos, e paga comissões e spread'],
      ['Corretora ou banco','Recebe e encaminha as tuas ordens; mantém a conta de valores','Comissões e outros serviços'],
      ['Bolsa (Euronext)','Gere o mercado e o livro de ordens','Taxas de negociação e de dados'],
      ['Market maker','Cota preços de compra e de venda continuamente','O spread, correndo risco de inventário'],
      ['Contraparte central (CCP)','Garante que o negócio se cumpre','Taxas de compensação'],
      ['Registo central de títulos (CSD)','Regista os titulares e liquida as trocas','Taxas de registo e liquidação']],
      cap:'Resumo dos papéis. Cada um vive de uma taxa ou de uma margem; nenhum «está do teu lado» por acaso.'},
    {t:'decide',id:'q2',ensina:['p3','p3b','c2'],label:'Decide',q:'Qual é o papel principal de um market maker?',o:['Garantir que as ações do mercado só sobem','Cotar de forma contínua preços de compra e de venda, dando liquidez ao mercado','Guardar as ações dos investidores','Decidir o preço oficial de cada ação'],c:1,why:'O market maker está sempre disposto a comprar e vender, o que permite que tu consigas negociar quando queres. Ganha o spread, e arrisca-se a ficar com ações que descem.'},
    {t:'h',id:'h4',x:'Quem guarda as tuas ações'},
    {t:'p',id:'p4',x:'As ações não existem em papel: são registos eletrónicos. Em Portugal o registo central dos valores mobiliários é feito pela Euronext Securities Porto, o nome comercial da Interbolsa (segundo a página da Euronext sobre o depositário central de Porto), que também liquida as operações dos mercados da Euronext Lisboa. Tu não tens conta lá: tens conta na corretora ou no banco, que é o participante, e é essa conta que mostra o que és titular.'},
    {t:'p',id:'p4b',x:'É o que se chama <b>custódia</b>. Quando mudas de corretora, transferes a custódia: é uma operação de transferência de valores, não precisas de vender e recomprar (ver o tema «Banco ou corretora?» para as diferenças entre intermediários).'},
    {t:'note',id:'n1',pending:true,x:'Por confirmar com a CMVM: as regras de segregação, que obrigam a manter os valores dos clientes separados dos bens da corretora, e as regras de melhor execução, que obrigam as corretoras a procurar o melhor resultado possível para o cliente. O princípio é conhecido, mas a redação exata deve ser confirmada na fonte oficial. A proteção da indemnização aos investidores está no tema «Sistema de Indemnização aos Investidores».'},
    {t:'h',id:'h5',x:'Hoje T+2, amanhã T+1'},
    {t:'p',id:'p5',x:'Hoje, nas bolsas da União Europeia, a liquidação é feita dois dias úteis depois do negócio (T+2). A Euronext indica que a transição para T+1, um dia útil depois, está marcada para 11 de outubro de 2027 em toda a UE e no Espaço Económico Europeu (verificado em 17/11/2026 no programa T+1 da Euronext). Ciclos mais curtos reduzem o tempo em que há risco de uma das partes falhar, mas exigem que as corretoras e os investidores tenham o dinheiro e as ações prontos mais depressa.'},
    {t:'fazve',id:'q3',ensina:['p5','u1'],q:'Se a liquidação é feita em T+2 e compras ações a uma segunda-feira (dia útil, sem feriados), em que dia da semana as ações são liquidadas, contando de 1 = segunda a 5 = sexta?',unit:'dia (1 a 5)',answer:3,tol:.01,why:'Segunda-feira mais dois dias úteis é quarta-feira, o dia 3. Se houvesse um feriado no meio, a liquidação passaria para quinta-feira. Em T+1 seria na terça-feira.'},
    {t:'h',id:'h6',x:'Um caso real: o «flash crash» de 2010'},
    {t:'p',id:'p6',x:'A 6 de maio de 2010, o mercado de ações dos EUA caiu fortemente em poucos minutos e voltou a subir quase tudo em seguida. Muitos dos intermediários que davam liquidez retiraram as ordens ao mesmo tempo, e as que ficaram foram executadas a preços muito afastados do normal. Algumas ações chegaram a negociar a preços absurdos, durante pouco tempo. O episódio mostrou que a liquidez pode desaparecer em segundos, e levou à criação de mecanismos de pausa automática nas bolsas quando os preços se mexem demasiado depressa.'},
    {t:'h',id:'h7',x:'Os erros que mais custam'},
    {t:'ul',id:'u2',x:[
      'Pensar que comprar é instantâneo e definitivo: a liquidação demora dias úteis e há casos em que a ordem não é executada.',
      'Ignorar o spread: em ações e ETFs pouco negociados pode custar mais do que a comissão da corretora.',
      'Dar ordens a mercado à abertura ou ao fecho, ou logo a seguir a notícias, em ativos pouco líquidos.',
      'Contar com o dinheiro de uma venda no próprio dia: pode só estar disponível depois da liquidação (e depende da corretora).',
      'Confundir quem guarda as ações (a custódia) com quem as gere ou aconselha.']},
    {t:'erro',id:'q4',ensina:['u1','p1','p3'],label:'Encontra o erro',q:'Uma destas frases sobre o funcionamento da bolsa está errada. Qual?',o:['A corretora encaminha as ordens para a bolsa','A contraparte central garante que o negócio se cumpre mesmo que uma das partes falhe','O market maker ganha o spread entre compra e venda','A liquidação é feita no mesmo segundo em que o negócio é fechado'],c:3,why:'Hoje a liquidação demora dois dias úteis (T+2) e passará a um (T+1) em outubro de 2027. O preço fixa-se no momento do negócio, mas a troca de ações por dinheiro vem depois.'},
    {t:'h',id:'h8',x:'Em Portugal'},
    {t:'p',id:'p7',x:'A Euronext Lisboa faz parte do grupo Euronext e é onde se negociam as empresas portuguesas cotadas (as do índice PSI, entre outras). O depositário central de títulos é a Euronext Securities Porto; tu falas com a tua corretora ou banco, nunca diretamente com a bolsa. Como estas entidades se organizam afeta o que pagas: vê os temas «Comissões e imposto do selo» e «Horários da Euronext Lisboa».'},
    {t:'h',id:'h9',x:'Em poucas palavras'},
    {t:'ul',id:'u3',x:[
      'A tua ordem vai da corretora para a bolsa, onde é cruzada; depois vêm a compensação, a liquidação e a custódia.',
      'O preço fixa-se ao cruzar as ordens; a troca de ações por dinheiro ocorre em T+2 (T+1 previsto para 11/10/2027).',
      'A abertura e o fecho costumam ser feitos por leilão, ao preço que maximiza o volume.',
      'Market makers dão liquidez e ganham o spread; para ti o spread é um custo escondido.',
      'As ações ficam registadas em nome do titular numa conta de custódia, mantida pela corretora ou banco.']}
  ], src:[
    {l:'Euronext: programa T+1',u:'https://www.euronext.com/en/regulation/t1-programme'},
    {l:'Euronext Securities Porto',u:'https://www.euronext.com/en/csd/porto'}] }
,
{ id:'indices', topic:'mercados', o:3, title:'Índices: S&P 500, PSI e Euro Stoxx 50', mins:7,
  lead:'Um índice é um termómetro: junta o preço de várias empresas num só número, para veres como vai um mercado inteiro sem olhares para cada ação. Quando ouves que «a bolsa subiu», é um índice que está a falar.',
  blocks:[
    {t:'h',id:'h0',x:'A média da turma'},
    {t:'p',id:'p0',x:'Se quiseres saber como vai uma turma de trinta alunos, não lês as trinta pautas: olhas para a média. Um índice faz o mesmo com as empresas. Seleciona um grupo de ações, junta o desempenho delas num único número e atualiza-o ao longo do dia. O que interessa não é o valor absoluto (5 000 pontos não quer dizer nada sozinho) mas a <b>variação</b>: se passou de 5 000 para 5 100, subiu 2%.'},
    {t:'p',id:'p1',x:'Um índice não se compra: é só um número que resume um grupo de ativos. O mais comum é <b>ponderar pelo valor de mercado</b>: as empresas maiores pesam mais do que as pequenas, por isso uma grande empresa a mexer-se muda mais o índice.'},
    {t:'cmp',id:'c1',head:['Índice','O que mede','Onde'],rows:[
      ['S&P 500','As 500 grandes empresas dos Estados Unidos','EUA'],
      ['Euro Stoxx 50','As 50 maiores empresas da Zona Euro','Zona Euro'],
      ['PSI','As principais empresas cotadas na Euronext Lisboa','Portugal']]},
    {t:'h',id:'h1',x:'Como se constrói um índice'},
    {t:'p',id:'p1b',x:'Um índice tem três ingredientes. Primeiro, uma <b>regra de seleção</b>: que empresas entram (por país, tamanho, setor, liquidez). Segundo, uma <b>regra de ponderação</b>: quanto pesa cada uma. Terceiro, uma <b>revisão periódica</b>: de tempos a tempos, as empresas que já não cumprem as regras saem e entram outras. Quem gere o índice (as entidades «fornecedoras de índices») publica as regras para toda a gente as conhecer.'},
    {t:'p',id:'p1c',x:'Há três formas habituais de ponderar:'},
    {t:'ul',id:'u1',x:[
      '<b>Pelo valor de mercado</b> (o mais comum, S&P 500 e Euro Stoxx 50): cada empresa pesa conforme a sua capitalização bolsista, normalmente só da parte das ações que estão realmente à venda no mercado (<i>free float</i>).',
      '<b>Pelo preço</b> (como o Dow Jones, nos EUA): pesa o preço da ação, o que é estranho, porque uma ação de preço alto pesa mais mesmo que a empresa seja pequena.',
      '<b>Igual para todas</b> (índices de «peso igual»): cada empresa pesa o mesmo, e o índice reequilibra-se periodicamente.']},
    {t:'h',id:'h2',x:'Uma conta pequena: a ponderação muda o resultado'},
    {t:'p',id:'p2a',x:`Imagina um mini-índice com três empresas. A vale 600 milhões, B vale 300 e C vale 100 (valor de mercado). Num ano, A sobe 10%, B fica igual e C cai 20%. Com ponderação por valor de mercado, as grandes empresas dominam: o índice sobe ${_mer_pt(_mer_idx.cap,1)}%. Com peso igual, a pequena pesa tanto como a grande, e o índice cai ${_mer_pt(-_mer_idx.igual,1)}%.`},
    {t:'cmp',id:'c2',head:['Empresa','Valor de mercado','Variação','Peso (mercado)','Peso (igual)'],rows:_mer_idx.rows.map(r=>[r.n,r.m+' M€',r.v+'%',_mer_pt(r.wm*100,0)+'%',_mer_pt(r.we*100,1)+'%']),cap:`Exemplo inventado. O mesmo grupo de empresas dá ${_mer_pt(_mer_idx.cap,1)}% ou ${_mer_pt(_mer_idx.igual,1)}% conforme a regra de ponderação.`},
    {t:'fazve',id:'q1',ensina:['p1','u1','p2a','c2'],q:'No mini-índice acima, com ponderação por valor de mercado, qual é a variação do índice no ano (em %)?',unit:'%',answer:_mer_idx.cap,tol:.03,why:`0,6 × 10% + 0,3 × 0% + 0,1 × (−20%) = ${_mer_pt(_mer_idx.cap,1)}%. As empresas grandes mandam: a queda da pequena pesa pouco no resultado final.`},
    {t:'h',id:'h3',x:'Preço ou retorno total?'},
    {t:'p',id:'p3',x:'Muitos índices são de <b>preço</b>: só refletem a subida e descida das cotações e ignoram os dividendos que as empresas pagam. Os de <b>retorno total</b> contam os dividendos como se fossem reinvestidos. A diferença parece pequena de ano para ano, mas acumula. Com um exemplo: se as cotações sobem 5% ao ano e os dividendos rendem 2%, ao fim de 20 anos:'},
    {t:'cmp',id:'c3',head:['Como mede','Subida anual','Valor de 10 000 € ao fim de 20 anos'],rows:[['Índice de preço (só cotações)','5%',_mer_eu(10000*Math.pow(1.05,20))],['Índice de retorno total (cotações e dividendos)','7%',_mer_eu(10000*Math.pow(1.07,20))]],cap:'Valores de exemplo, sem custos nem impostos. Quando vês a rentabilidade de um índice, verifica se é de preço ou de retorno total.'},
    {t:'p',id:'p3b',x:'Os valores que ouves nas notícias são quase sempre de índices de preço. É por isso que o retorno real de quem investe e reinveste dividendos (por exemplo, num ETF de acumulação) é, a longo prazo, mais alto do que o do índice que vês nos gráficos.'},
    {t:'h',id:'h4',x:'Para que serve na prática'},
    {t:'p',id:'p2',x:'Como um índice não se compra, investes nele através de um <b>ETF</b> que o replica. A rentabilidade que vês anunciada para o «S&P 500» é a do índice, e o teu ETF ficará ligeiramente abaixo por causa dos custos. Vê no tema dos ETFs quais se compram em Portugal.'},
    {t:'p',id:'p3c',x:'Os índices também servem de <b>referência</b>: se a tua carteira subiu 6% e o mercado em geral subiu 12%, ficaste atrás, mesmo que tenhas ganho dinheiro.'},
    {t:'decide',id:'q2',ensina:['p2'],label:'Decide',q:'Queres investir «no S&P 500». O que fazes na prática?',o:['Compro o índice diretamente','Compro uma ação chamada S&P 500','Compro um ETF que replica o índice'],c:2,why:'O índice é só um número. Para investir nele compras um produto que o replica, como um ETF.'},
    {t:'decide',id:'q3',ensina:['p1','c1'],label:'Decide',q:'Qual índice te diria como vai o conjunto das principais empresas cotadas em Lisboa?',o:['PSI','S&P 500','Euro Stoxx 50'],c:0,why:'O PSI agrupa as principais empresas cotadas na Euronext Lisboa. O S&P 500 é americano e o Euro Stoxx 50 é da Zona Euro.'},
    {t:'h',id:'h5',x:'Os índices mais conhecidos'},
    {t:'cmp',id:'c4',head:['Índice','Quantas empresas','Como pondera','Mercado'],rows:[
      ['S&P 500','500','Valor de mercado (ajustado ao free float)','Grandes empresas dos EUA'],
      ['Dow Jones Industrial Average','30','Pelo preço das ações','Grandes empresas dos EUA'],
      ['Nasdaq-100','100','Valor de mercado, com ajustes','Maiores empresas não financeiras da Nasdaq, muita tecnologia'],
      ['Euro Stoxx 50','50','Valor de mercado (ajustado ao free float)','Zona Euro'],
      ['PSI','Varia (confirma no site da Euronext)','Valor de mercado','Portugal']],
      cap:'Resumo geral: confirma sempre a ficha do índice junto de quem o gere, porque as regras e o número de empresas podem mudar.'},
    {t:'h',id:'h6',x:'Um caso real: o Dow Jones, o índice que muda de empresas'},
    {t:'p',id:'p5',x:'O Dow Jones nasceu em 1896, criado por Charles Dow, com doze empresas, quase todas industriais. Hoje tem trinta e o negócio delas é muito diferente: as empresas que perderam importância foram saindo, e a General Electric, uma das doze originais, só deixou o índice em 2018. Isto mostra um aspeto importante: <b>um índice limpa-se a si próprio</b>. As empresas que vão mal saem e as que crescem entram, por isso a história de um índice parece mais bonita do que a de uma carteira de empresas fixas.'},
    {t:'h',id:'h7',x:'Os erros que mais custam'},
    {t:'ul',id:'u2',x:[
      'Achar que se pode «comprar o índice»: compra-se um produto que o replica, com custos.',
      'Comparar o retorno do teu ETF com um índice de preço, quando o teu ETF acumula dividendos (ou ao contrário).',
      'Pensar que 500 empresas são 500 apostas iguais: um pequeno grupo de empresas gigantes pode pesar uma fatia grande do índice.',
      'Confundir o nível do índice com «caro» ou «barato»: o valor em pontos é arbitrário.',
      'Comparar índices de países sem ter em conta a moeda e os dividendos.']},
    {t:'erro',id:'q4',ensina:['p1','p1b','u1','c3'],label:'Encontra o erro',q:'Uma destas frases sobre índices está errada. Qual?',o:['Um índice de retorno total conta os dividendos reinvestidos','Num índice ponderado por valor de mercado, as empresas maiores pesam mais','Um índice ao nível dos 5 000 pontos é necessariamente caro, e um a 500 é barato','As empresas do índice mudam com o tempo, conforme as regras'],c:2,why:'O nível em pontos depende da data de início e da fórmula: não diz se o mercado está caro. Só as variações e as comparações com os lucros (tema «PER e outros rácios») dizem alguma coisa.'},
    {t:'h',id:'h8',x:'Em Portugal'},
    {t:'p',id:'p6',x:'O PSI é o índice de referência da Euronext Lisboa e reflete um mercado pequeno, concentrado em poucos setores (por exemplo, energia, distribuição e serviços públicos), por isso diversifica pouco só por si. Para investir lá fora, no S&P 500, por exemplo, há versões «UCITS» que se compram em Portugal (vê o tema «ETFs e diversificação: o que se compra em Portugal»). Os ETFs americanos como VOO ou SPY não se compram a partir de Portugal.'},
    {t:'h',id:'h9',x:'Em poucas palavras'},
    {t:'ul',id:'u3',x:[
      'Um índice resume um grupo de ações num número; o que interessa é a variação, não o valor absoluto.',
      'Constrói-se com regras de seleção, ponderação (valor de mercado, preço ou igual) e revisão periódica.',
      'A ponderação muda o resultado: dois índices com as mesmas empresas podem ter retornos muito diferentes.',
      'Índices de preço ignoram dividendos; os de retorno total contam-nos.',
      'Não se compra um índice, mas sim um produto que o replica (ETF), com custos e a possibilidade de risco cambial.']}
  ], src:[] }
,
{ id:'setores-capitalizacao', topic:'mercados', o:4, title:'Setores e capitalização: large, mid e small caps, defensivos e cíclicos', mins:7,
  lead:'Uma bolsa não é um bloco único: as empresas dividem-se por setor (o que vendem) e por tamanho (quanto valem em bolsa). Estas duas «etiquetas» explicam muito do comportamento de cada ação em cada fase da economia.',
  blocks:[
    {t:'h',id:'h0',x:'As secções do supermercado'},
    {t:'p',id:'p0',x:'Num supermercado há secções (frescos, limpeza, eletrónica, roupa) e lojas de vários tamanhos (a mercearia do bairro, o hipermercado). Quando o dinheiro aperta, as pessoas continuam a comprar leite e pasta de dentes, mas adiam a televisão nova. Quando há mais folga, o contrário. A bolsa é igual: empresas de setores diferentes reagem de forma diferente ao mesmo cenário, e empresas pequenas não se comportam como as grandes.'},
    {t:'h',id:'h1',x:'Os setores'},
    {t:'p',id:'p1',x:'As empresas agrupam-se em <b>setores</b> segundo o que vendem. A classificação internacional mais usada (GICS, mantida por S&P e MSCI) divide as empresas em onze setores. Não precisas de os decorar, mas convém reconhecer os grupos e perceber a que é que cada um é sensível.'},
    {t:'cmp',id:'c1',head:['Setor','Que negócios','Costuma comportar-se como','Sensível sobretudo a'],rows:[
      ['Energia','Petróleo, gás, refinarias','Cíclico','Preço do petróleo e do gás'],
      ['Materiais','Química, metais, papel e celulose','Cíclico','Procura mundial e matérias-primas'],
      ['Industriais','Construção, máquinas, transportes','Cíclico','Investimento das empresas e comércio'],
      ['Consumo discricionário','Carros, viagens, restaurantes, vestuário','Cíclico','Rendimento e confiança das famílias'],
      ['Bens de consumo básico','Alimentação, bebidas, higiene, supermercados','Defensivo','Poucas oscilações; custos das matérias-primas'],
      ['Saúde','Farmacêuticas, hospitais, equipamento médico','Defensivo','Regulação e inovação'],
      ['Serviços públicos (utilities)','Eletricidade, gás, água','Defensivo','Taxas de juro (muita dívida) e regulação'],
      ['Financeiro','Bancos, seguradoras, gestoras','Cíclico','Taxas de juro, ciclo económico, crédito mal parado'],
      ['Tecnologia','Software, equipamentos, semicondutores','Cíclico / crescimento','Taxas de juro e expectativas de lucro'],
      ['Serviços de comunicação','Telecomunicações, media, plataformas','Misto','Publicidade e subscrições'],
      ['Imobiliário','Imobiliário cotado, REITs','Sensível a taxas','Taxas de juro e ocupação']],
      cap:'Classificação simplificada e tendências gerais, não regras. Cada empresa tem as suas particularidades.'},
    {t:'h',id:'h2',x:'Cíclicos e defensivos'},
    {t:'p',id:'p2',x:'Os <b>cíclicos</b> são setores cujos lucros sobem e descem muito com o ciclo económico (tema «Ciclos económicos e recessões»): quando a economia cresce, vendem mais; quando abranda, vendem muito menos. Os <b>defensivos</b> vendem coisas de que as pessoas precisam em qualquer fase (comida, medicamentos, eletricidade), por isso têm lucros mais estáveis e costumam cair menos nas crises, mas também sobem menos nas fases de euforia.'},
    {t:'p',id:'p2b',x:'«Cair menos» não é «não cair». Em 2008, por exemplo, quase todos os setores caíram; os defensivos perderam menos, mas perderam. E a diferença conta pela matemática das quedas: uma queda de 10% exige uma subida de 11,1% para recuperar, enquanto uma de 30% exige 42,9%. Podes verificar com a calculadora:'},
    {t:'w',id:'w1',w:'calc',c:'drawdown'},
    {t:'fazve',id:'q1',ensina:['p2b','w1'],q:'Um setor cíclico cai 30% numa crise. Quanto tem de subir (em %) para recuperar o valor anterior?',unit:'%',answer:_c('drawdown',{val:1000,q:30})[1],tol:.02,why:`100 caiu para 70, e 70 × 1,4286 = 100. A subida necessária é cerca de ${_mer_pt(_c('drawdown',{val:1000,q:30})[1],1)}%, mais do que os 30% da queda. Com os defensivos a cair só 10%, a recuperação precisa só de cerca de ${_mer_pt(_c('drawdown',{val:1000,q:10})[1],1)}%.`},
    {t:'h',id:'h3',x:'As taxas de juro mexem nos setores de forma diferente'},
    {t:'ul',id:'u1',x:[
      '<b>Bancos</b> costumam beneficiar de taxas mais altas (a diferença entre o que cobram nos créditos e o que pagam nos depósitos aumenta), mas sofrem se houver muito crédito mal pago.',
      '<b>Serviços públicos e imobiliário</b> têm muita dívida e pagam dividendos estáveis: com taxas mais altas, a dívida custa mais e as obrigações, que ficam a pagar mais, concorrem com os dividendos. Tendem a sofrer.',
      '<b>Tecnologia e empresas de crescimento</b> valem sobretudo pelos lucros de daqui a muitos anos; taxas mais altas «descontam» esses lucros mais, por isso tendem a sofrer.',
      '<b>Energia e materiais</b> dependem mais do preço das matérias-primas do que dos juros.']},
    {t:'h',id:'h4',x:'O tamanho: large, mid e small caps'},
    {t:'p',id:'p3',x:'O tamanho de uma empresa mede-se pela capitalização bolsista (preço × número de ações; tema «O que é a bolsa e como se formam os preços»). As <b>large caps</b> são as maiores, as <b>mid caps</b> são as médias e as <b>small caps</b> são as pequenas. Não há um limite universal em euros: cada fornecedor de índices usa os seus e eles mudam com o tempo e com os mercados.'},
    {t:'cmp',id:'c2',head:['','Large caps','Mid caps','Small caps'],rows:[
      ['Tamanho','Grandes empresas, muito conhecidas','Empresas médias','Empresas pequenas, muitas vezes menos conhecidas'],
      ['Estabilidade dos lucros','Em geral mais estável','Intermédia','Em geral mais volátil'],
      ['Liquidez (facilidade de comprar e vender)','Alta, spreads pequenos','Média','Mais baixa, spreads maiores'],
      ['Potencial de crescimento','Mais limitado pelo tamanho','Intermédio','Maior, mas com mais risco de falhar'],
      ['Dividendos','Frequentemente mais regulares','Variáveis','Costumam reinvestir mais e pagar menos'],
      ['Peso nos índices (ponderados por valor de mercado)','Domina','Moderado','Pequeno']],
      cap:'Tendências gerais. Há exceções em todas as colunas.'},
    {t:'p',id:'p3b',x:'Em geral, as small caps oscilam mais e tendem a cair mais nas crises, mas historicamente também deram, em certos períodos, mais retorno, como compensação pelo risco. Não é garantido e varia muito consoante o período e o mercado.'},
    {t:'decide',id:'q2',ensina:['p2','c1'],label:'Decide',q:'A economia está a entrar em recessão. Qual destes grupos de empresas tende a ser menos afetado?',o:['Restaurantes e companhias de viagens','Fabricantes de automóveis de luxo','Supermercados e empresas de eletricidade'],c:2,why:'Eletricidade e alimentação são necessidades: continuam a ser consumidas em recessão. Viagens, restaurantes e carros de luxo são despesas que se adiam.'},
    {t:'h',id:'h5',x:'Um caso real: 2020 e 2022 em direções opostas'},
    {t:'p',id:'p4',x:'Em 2020, com os confinamentos, as empresas de viagens, restauração e energia caíram muito, enquanto a tecnologia e o comércio online subiram. Em 2022, a história virou: a subida das taxas de juro feriu a tecnologia e o crescimento, e a energia, com os preços do petróleo e do gás em alta, foi dos setores que melhor se comportou. Dois anos seguidos de movimentos fortes em sentidos contrários, só por mudar o contexto.'},
    {t:'p',id:'p4b',x:'A lição é que nenhum setor «ganha sempre». Quem concentra tudo num só setor depende de uma aposta no cenário certo. Quem se diversifica por vários setores e tamanhos aceita nunca ter o melhor resultado, mas também não fica com o pior.'},
    {t:'h',id:'h6',x:'Os erros que mais custam'},
    {t:'ul',id:'u2',x:[
      'Achar que ter 20 ações é estar diversificado quando todas são do mesmo setor.',
      'Pensar que um setor «defensivo» não cai. Cai menos, em média, não nunca.',
      'Tentar adivinhar quando um setor vai ser o próximo vencedor: a rotação entre setores é difícil de prever e cara de executar.',
      'Ignorar o peso dos setores num ETF ou fundo: um índice pode estar muito concentrado em poucas empresas ou setores.',
      'Investir em small caps sem contar com spreads maiores e com a dificuldade de vender depressa.',
      'Concentrar o património no setor onde trabalhas ou na empresa do teu empregador.']},
    {t:'erro',id:'q3',ensina:['p2','p2b','u2'],label:'Encontra o erro',q:'Uma destas frases sobre setores e tamanhos está errada. Qual?',o:['Setores defensivos vendem produtos de que as pessoas precisam em qualquer fase','Os cíclicos costumam sofrer mais numa recessão','Small caps são sempre mais seguras do que large caps porque são mais pequenas','Large caps costumam ter spreads mais pequenos do que small caps'],c:2,why:'Small caps costumam ser mais voláteis e menos líquidas. Ser pequena não torna uma empresa mais segura: normalmente dá o efeito contrário.'},
    {t:'h',id:'h7',x:'Em Portugal'},
    {t:'p',id:'p5',x:'O mercado português é pequeno e as empresas do PSI concentram-se em poucos setores (por exemplo, energia, serviços públicos, distribuição, papel e banca), pelo que investir só em Portugal dá uma diversificação setorial fraca. A solução comum é usar ETFs UCITS que cobrem os mercados globais ou europeus, onde há muito mais setores representados (tema «ETFs e diversificação: o que se compra em Portugal»). Há também ETFs de setores específicos e de small caps, mas convém conhecer bem o que se compra e os custos.'},
    {t:'note',id:'n1',pending:true,x:'A composição por setores do PSI muda com as revisões da Euronext. Por confirmar na ficha oficial do índice antes de tirares conclusões sobre o peso de cada setor.'},
    {t:'h',id:'h8',x:'Em poucas palavras'},
    {t:'ul',id:'u3',x:[
      'As empresas agrupam-se em setores (onze na classificação GICS) e em tamanhos (large, mid, small caps).',
      'Cíclicos acompanham a economia; defensivos vendem o que se compra sempre e caem, em média, menos nas crises.',
      'Taxas de juro mais altas tendem a ajudar bancos e a pesar em utilities, imobiliário e tecnologia.',
      'Small caps oscilam mais e são menos líquidas; large caps dominam os índices.',
      'Diversificar por setores e por tamanhos reduz a dependência de uma única aposta.']},
    {t:'decide',id:'q4',ensina:['c2','p3b','p4b'],label:'Decide',q:'Um índice ponderado por valor de mercado tem 500 empresas, mas as 10 maiores pesam uma parte muito grande do total. O que isso implica?',o:['Que o índice está perfeitamente equilibrado entre as 500 empresas','Que o comportamento do índice depende muito das empresas grandes','Que as small caps dominam o índice'],c:1,why:'Na ponderação por valor de mercado, as maiores empresas mandam. Com poucas empresas muito grandes, o índice reflete sobretudo o que elas fazem, e não 500 apostas iguais.'}
  ], src:[] }
,
{ id:'bancos-centrais', topic:'mercados', o:5, title:'Bancos centrais e taxas de juro', mins:8,
  lead:'O banco central controla o preço do dinheiro. Quando sobe ou desce as taxas de juro, mexe no custo dos créditos, no que os depósitos pagam e no preço de quase todos os ativos. É a decisão económica com mais efeito no teu dia a dia.',
  blocks:[
    {t:'h',id:'h0',x:'O termóstato da economia'},
    {t:'p',id:'p0',x:'Pensa num termóstato. Se a casa está demasiado quente, desliga o aquecimento; se está fria, liga-o. O banco central faz algo parecido com a economia. Quando está a «aquecer» demais (preços a subir depressa), sobe as taxas de juro para arrefecer; quando está a «arrefecer» demais (desemprego a subir, atividade fraca), desce-as para estimular. O instrumento é o preço do dinheiro.'},
    {t:'p',id:'p1',x:'Na Zona Euro quem decide é o <b>Banco Central Europeu (BCE)</b>, que tem como objetivo principal manter os preços estáveis, com uma inflação à volta de 2% a médio prazo. Se a inflação está acima, tende a <b>subir</b> as taxas para arrefecer a economia; se a economia está fraca, tende a <b>descê-las</b>.'},
    {t:'p',id:'p1b',x:'O objetivo do BCE é <b>simétrico</b>: uma inflação muito baixa é tão indesejável como uma muito alta (verificado em 17/11/2026 na declaração de estratégia do BCE, em ecb.europa.eu). E o principal instrumento são as <b>taxas de juro diretoras</b> do BCE, que ele fixa nas reuniões de política monetária, cerca de oito por ano.'},
    {t:'h',id:'h1',x:'Das taxas do BCE às tuas contas'},
    {t:'p',id:'p2',x:'As taxas do BCE influenciam a <b>Euribor</b>, a taxa a que os bancos se emprestam entre si, que serve de base a muitos créditos e a alguns produtos de poupança. Por isso, quando as taxas sobem, as prestações de créditos indexados à Euribor sobem e os depósitos tendem a pagar mais.'},
    {t:'cmp',id:'c1',head:['Canal','O que acontece quando o BCE sobe as taxas','O que acontece quando as desce'],rows:[
      ['Créditos a taxa variável','Prestação sobe (Euribor sobe)','Prestação desce'],
      ['Depósitos e poupança','Tendem a pagar mais','Tendem a pagar menos'],
      ['Obrigações já emitidas','Perdem valor (ver abaixo)','Ganham valor'],
      ['Ações','Pressão, sobretudo em empresas endividadas e de crescimento','Apoio, sobretudo nas mesmas'],
      ['Euro','Tende a fortalecer-se','Tende a enfraquecer-se'],
      ['Economia','Arrefece o consumo e o investimento','Estimula o consumo e o investimento']],
      cap:'São tendências, não regras. Os mercados antecipam as decisões, e outros fatores contam ao mesmo tempo.'},
    {t:'h',id:'h2',x:'Efeito nos investimentos'},
    {t:'ul',id:'u1',x:[
      '<b>Obrigações já emitidas</b> tendem a perder valor quando as taxas sobem, porque aparecem outras novas que pagam mais.',
      '<b>Ações</b> de empresas muito endividadas ou que valem sobretudo pelos lucros futuros tendem a sofrer mais com taxas altas.',
      '<b>Depósitos e poupança</b> passam a render mais.']},
    {t:'p',id:'p2b',x:`Vê a lógica com um exemplo. Uma obrigação que paga 100 € daqui a 10 anos, sem cupões (uma conta mais simples), vale hoje ${_mer_e2(_mer_zc(3,10))} se o mercado exigir 3% ao ano. Se as taxas subirem para 4%, a mesma obrigação passa a valer ${_mer_e2(_mer_zc(4,10))}: uma queda de ${_mer_pt((1-_mer_zc(4,10)/_mer_zc(3,10))*100,1)}%, só porque as taxas subiram um ponto. Quem a vendeu antes do vencimento perdeu; quem a manteve até ao fim recebeu os 100 €.`},
    {t:'h',id:'h3',x:'O que uma subida de taxas faz a uma prestação'},
    {t:'p',id:'p3',x:'Vê o efeito de uma taxa mais alta na prestação de um crédito:'},
    {t:'w',id:'w1',w:'calc',c:'debt'},
    {t:'fazve',id:'q1',ensina:['p3','w1'],q:'Um crédito de 10 000 € a 5 anos custa cerca de 202,76 € por mês a 8%. Se a taxa nominal fosse 10%, qual seria a prestação aproximada?',unit:'€',answer:_c('debt',{cap:10000,tax:10,ano:5})[0],tol:.02,why:'Cerca de 212,47 € por mês. Mais 2 pontos percentuais de taxa são quase 10 € a mais todos os meses, durante 5 anos.'},
    {t:'p',id:'p3b',x:`A diferença é muito maior em créditos longos. Um crédito à habitação de 100 000 € a 30 anos custa ${_mer_e2(_c('debt',{cap:100000,tax:3,ano:30})[0])} por mês se a taxa for 3% (por exemplo, Euribor de 2% mais spread de 1%) e ${_mer_e2(_c('debt',{cap:100000,tax:5,ano:30})[0])} se for 5%: mais ${_mer_e2(_c('debt',{cap:100000,tax:5,ano:30})[0]-_c('debt',{cap:100000,tax:3,ano:30})[0])} por mês, todos os meses, durante anos (valores de exemplo, sem seguros nem comissões).`},
    {t:'decide',id:'q2',ensina:['p1','p1b'],label:'Decide',q:'A inflação está muito acima de 2% e a economia está a aquecer. O que tende a fazer o BCE?',o:['Descer as taxas de juro','Não fazer nada nunca','Subir as taxas de juro'],c:2,why:'Taxas mais altas encarecem o crédito e travam o consumo e o investimento, o que ajuda a baixar a inflação.'},
    {t:'h',id:'h4',x:'Outras ferramentas e outros bancos centrais'},
    {t:'p',id:'p4',x:'Além das taxas, os bancos centrais podem comprar obrigações em grande escala para injetar dinheiro e baixar as taxas de longo prazo, a chamada <b>flexibilização quantitativa</b> (QE, do inglês). O BCE fê-lo a partir de 2015 e outra vez na pandemia, em 2020. Quando quer fazer o contrário, deixa a carteira encolher (<b>QT</b>). Estas medidas afetam as obrigações e, indiretamente, as ações e os câmbios.'},
    {t:'p',id:'p4b',x:'Outros bancos centrais importantes são a <b>Reserva Federal</b> (Fed) dos EUA, o Banco de Inglaterra e o Banco do Japão. A Fed pesa especialmente: o dólar é a moeda de reserva mundial, e as decisões dela mexem com os mercados de todo o mundo, incluindo a Europa.'},
    {t:'note',id:'n1',pending:true,x:'O BCE tem mais do que uma taxa diretora (a das operações principais de refinanciamento, a da facilidade permanente de depósito e a da facilidade de cedência). Qual delas é a referência de política monetária mudou com a alteração do quadro operacional. Por confirmar a descrição exata no site do BCE antes de a citares.'},
    {t:'h',id:'h5',x:'Um caso real: «whatever it takes»'},
    {t:'p',id:'p5',x:'Em 2011 e 2012, a Zona Euro viveu a crise da dívida soberana. Os juros que países como Portugal, a Grécia ou a Itália pagavam para se financiarem subiram a níveis insustentáveis, e chegou a duvidar-se da própria sobrevivência do euro. Em julho de 2012, o presidente do BCE, Mario Draghi, disse que o BCE faria «tudo o que fosse preciso» para preservar o euro. Só com essa frase, antes de qualquer compra de obrigações, os juros desses países começaram a descer.'},
    {t:'p',id:'p5b',x:'O episódio mostra o poder da <b>confiança</b>: os mercados reagem ao que o banco central diz que fará. Mais recentemente, entre 2022 e 2023, o BCE subiu as taxas várias vezes seguidas para travar a inflação, depois de anos de taxas muito baixas, e o impacto nas prestações dos créditos à habitação foi sentido por muitas famílias.'},
    {t:'h',id:'h6',x:'Os erros que mais custam'},
    {t:'ul',id:'u2',x:[
      'Achar que o banco central controla todas as taxas: controla as suas, e as dos mercados reagem às expectativas.',
      'Pensar que «taxas a subir» significa «bolsa a descer» sempre; a reação depende do que já estava no preço e do porquê da subida.',
      'Esperar um corte de taxas para investir: o mercado costuma antecipar e já ter subido quando o corte chega.',
      'Pedir um crédito a taxa variável sem testar se aguentas uma Euribor 2 a 3 pontos acima.',
      'Ignorar o efeito nas obrigações que tens: se vendes antes do vencimento, perdes quando as taxas sobem.']},
    {t:'erro',id:'q3',ensina:['p2','p2b','c1'],label:'Encontra o erro',q:'Uma destas frases sobre taxas de juro está errada. Qual?',o:['Quando as taxas sobem, os créditos indexados à Euribor ficam mais caros','Quando as taxas sobem, as obrigações já emitidas tendem a perder valor','O BCE fixa diretamente a Euribor','Os depósitos tendem a pagar mais quando as taxas sobem'],c:2,why:'A Euribor é fixada pelo mercado, a partir do que os bancos praticam entre si. As taxas do BCE influenciam-na, mas não a fixam.'},
    {t:'h',id:'h7',x:'Em Portugal'},
    {t:'p',id:'p6',x:'O Banco de Portugal faz parte do Eurosistema: não decide sozinho as taxas, mas participa nas decisões do BCE e supervisiona os bancos. Na prática, a Euribor sobe e desce e arrasta a prestação de muitos créditos à habitação. Os Certificados de Aforro Série F têm uma taxa base ligada à Euribor a 3 meses (com limites entre 0% e 2,5%), a que se soma um prémio de permanência (verificado em 17/11/2026 no IGCP): são um bom exemplo de um produto que reage às decisões do BCE. Vê também os temas «Certificados de Aforro e do Tesouro», «Depósitos a prazo» e «Dívida boa e dívida má».'},
    {t:'h',id:'h8',x:'Em poucas palavras'},
    {t:'ul',id:'u3',x:[
      'O BCE tem como objetivo uma inflação de 2% a médio prazo, e o instrumento principal são as taxas de juro diretoras.',
      'Taxas a subir: créditos mais caros, depósitos mais bem pagos, obrigações já emitidas a perder valor, pressão sobre ações de crescimento.',
      'A Euribor é a taxa de referência de muitos créditos: sobe e desce com as expectativas sobre as decisões do BCE.',
      'Os mercados reagem sobretudo às surpresas e ao que o banco central diz que vai fazer.',
      'Testa sempre o orçamento com uma taxa mais alta antes de assumir um crédito.']}
  ], src:[
    {l:'BCE: declaração de estratégia de política monetária (2025)',u:'https://www.ecb.europa.eu/mopo/strategy/strategy-review/ecb.strategyreview202506_strategy_statement.pt.html'},
    {l:'IGCP: Certificados de Aforro',u:'https://www.igcp.pt'}] }
,
{ id:'indicadores-macro', topic:'mercados', o:6, title:'Indicadores macro: PIB, desemprego, inflação, PMI', mins:8,
  lead:'Os indicadores macroeconómicos são o painel de instrumentos da economia: mostram se vai depressa ou devagar, se está a aquecer ou a arrefecer. Saber o que cada um mede, quem o publica e como o ler evita muitos enganos ao ouvir as notícias.',
  blocks:[
    {t:'h',id:'h0',x:'O painel do carro'},
    {t:'p',id:'p0',x:'Num carro tens vários mostradores: velocidade, combustível, temperatura do motor. Nenhum diz tudo sozinho, mas juntos dão uma boa ideia de como vai a viagem. A economia também tem um painel. Alguns indicadores dizem onde estás (a velocidade já alcançada), outros dizem para onde vais (o que as empresas esperam), e outros confirmam o que já aconteceu (atrasados). Convém saber distinguir.'},
    {t:'h',id:'h1',x:'PIB: o tamanho da economia'},
    {t:'p',id:'p1',x:'O <b>Produto Interno Bruto (PIB)</b> mede o valor de tudo o que um país produz num período (bens e serviços finais). Em Portugal é calculado e publicado pelo <b>INE</b>, nas Contas Nacionais trimestrais, e na União Europeia o <b>Eurostat</b> publica o PIB da Zona Euro e de cada país. Há duas formas de falar dele: <b>variação em cadeia</b> (face ao trimestre anterior) e <b>variação homóloga</b> (face ao mesmo trimestre do ano anterior).'},
    {t:'p',id:'p1b',x:`Uma distinção importante é a entre PIB <b>nominal</b> (a preços do dia) e <b>real</b> (descontada a inflação). Se o PIB nominal cresce 5% e os preços sobem 3%, o crescimento real é só (1,05 ÷ 1,03 − 1) = ${_mer_pt((1.05/1.03-1)*100,2)}%. Quando se fala em «a economia cresceu», fala-se quase sempre do PIB real. E para comparar trimestres: um crescimento de 0,5% num trimestre, se se mantivesse durante quatro trimestres, daria cerca de ${_mer_pt((Math.pow(1.005,4)-1)*100,2)}% ao ano.`},
    {t:'fazve',id:'q1',ensina:['p1b'],q:'O PIB nominal de um país cresce 5% num ano e a inflação é de 3%. Qual é, em %, o crescimento real, aproximadamente?',unit:'%',answer:(1.05/1.03-1)*100,tol:.05,why:`(1,05 ÷ 1,03) − 1 ≈ ${_mer_pt((1.05/1.03-1)*100,2)}%. Parte do crescimento «de papel» foi só a subida de preços, e o que interessa é a parte real.`},
    {t:'h',id:'h2',x:'Desemprego: quanta gente quer trabalhar e não consegue'},
    {t:'p',id:'p2',x:'A <b>taxa de desemprego</b> é o peso dos desempregados na população ativa. Segundo a definição estatística usada pelo INE e pelo Eurostat, é desempregada uma pessoa sem trabalho remunerado, disponível para trabalhar e que procurou ativamente emprego num período recente (os detalhes, como as idades e o período de procura, vêm na metainformação do INE e podem mudar com o tempo). A <b>população ativa</b> é a soma dos empregados com os desempregados.'},
    {t:'p',id:'p2b',x:`Um pormenor que surpreende: a taxa pode descer sem se criar emprego. Se há 5 000 desempregados numa população ativa de 100 000, a taxa é ${_mer_pt(5000/100000*100,1)}%. Se 1 000 desses desempregados desistem de procurar trabalho, deixam de contar como ativos e a taxa passa a ${_mer_pt(4000/99000*100,2)}%, apesar de ninguém ter ficado empregado. Por isso o INE publica também a taxa de subutilização do trabalho, que apanha quem trabalha menos horas do que queria ou quer trabalhar mas não procura.`},
    {t:'fazve',id:'q2',ensina:['p2','p2b'],q:'Numa população ativa de 200 000 pessoas há 12 000 desempregados. Qual é a taxa de desemprego, em %?',unit:'%',answer:12000/200000*100,tol:.01,why:'12 000 ÷ 200 000 = 6%. A taxa divide os desempregados pela população ativa (empregados mais desempregados), e não pela população total.'},
    {t:'h',id:'h3',x:'Inflação: quanto sobem os preços'},
    {t:'p',id:'p3',x:'A inflação já foi explicada no tema «Porque é que o dinheiro parado perde valor». Em Portugal o INE publica o IPC todos os meses, e o Eurostat publica o IHPC da Zona Euro (a «estimativa rápida» sai no fim do próprio mês). Os analistas olham também para a <b>inflação subjacente</b>, que exclui as componentes mais voláteis (como energia e alimentos não transformados), para perceber a tendência de fundo.'},
    {t:'h',id:'h4',x:'PMI: o que as empresas esperam'},
    {t:'p',id:'p4',x:'O <b>PMI</b> (Purchasing Managers Index, ou índice dos gestores de compras) não é um dado oficial: é um inquérito mensal a gestores de compras de empresas, feito por uma empresa privada, a S&P Global (no caso da Zona Euro, apresentado com o patrocínio do banco HCOB). Pergunta-se se as encomendas, a produção, o emprego e os preços subiram, desceram ou ficaram iguais face ao mês anterior. É um <b>índice de difusão</b>: percentagem de respostas «melhor» mais metade da percentagem de «igual».'},
    {t:'p',id:'p4b',x:`O ponto de corte é <b>50</b>: acima de 50, a maioria das empresas indica expansão; abaixo, contração. Por exemplo, se 40% dizem «melhor», 40% «igual» e 20% «pior», o índice é ${_mer_pmi(40,40)} (40 + 0,5 × 40). Como sai muito cedo (no fim ou logo a seguir ao mês em que se refere) e reflete o que as empresas já estão a viver, é considerado um indicador <b>adiantado</b>: costuma mostrar a tendência antes de o PIB a mostrar.`},
    {t:'fazve',id:'q3',ensina:['p4','p4b'],q:'Num inquérito, 30% das empresas dizem que a atividade melhorou, 50% que ficou igual e 20% que piorou. Qual é o valor do índice de difusão (estilo PMI)?',unit:'pontos',answer:_mer_pmi(30,50),tol:.01,why:`30 + 0,5 × 50 = ${_mer_pmi(30,50)}. Acima de 50 sinaliza expansão: aqui há mais empresas a melhorar do que a piorar.`},
    {t:'h',id:'h5',x:'Quem publica, com que frequência, e quando chegam'},
    {t:'cmp',id:'c1',head:['Indicador','O que mede','Quem publica','Frequência','Tipo'],rows:[
      ['PIB','Produção total da economia','INE (Portugal), Eurostat (UE)','Trimestral, com estimativa rápida','Coincidente, com atraso'],
      ['Desemprego','Peso dos desempregados na população ativa','INE, Eurostat','Mensal (estimativa) e trimestral','Atrasado'],
      ['Inflação (IPC / IHPC)','Variação dos preços do cabaz','INE, Eurostat','Mensal, com estimativa rápida','Coincidente'],
      ['PMI','Inquérito aos gestores de compras','S&P Global (com o HCOB na Zona Euro)','Mensal','Adiantado'],
      ['Decisões e projeções de taxas','O que o banco central fez e prevê','BCE, Banco de Portugal','Reuniões e projeções periódicas','Política económica']],
      cap:'Resumo. Há muitos mais indicadores: confiança dos consumidores, vendas a retalho, produção industrial, balança comercial. O calendário do site lista os da semana.'},
    {t:'h',id:'h6',x:'Como ler um número sem cair em armadilhas'},
    {t:'ul',id:'u1',x:[
      '<b>Surpresa, não valor</b>: o mercado já esperava um número. O que mexe é a diferença entre o que saiu e o que se previa (ver tema «Como ler o calendário económico»).',
      '<b>Revisões</b>: os primeiros valores são estimativas e podem ser corrigidos mais tarde, às vezes de forma notória.',
      '<b>Efeito de base</b>: uma variação homóloga alta pode vir de o ano anterior ter sido muito mau, e não de a economia estar a ir muito bem.',
      '<b>Dessazonalização</b>: muitos dados são ajustados para retirar o efeito da época do ano (Natal, férias), para que se possam comparar meses diferentes.']},
    {t:'p',id:'p5',x:`Um exemplo do efeito de base: um índice de atividade desce de 100 para 90 (menos 10%) e no ano seguinte sobe 10%, para ${_mer_pt(90*1.1,0)}. A «variação de +10%» soa a recuperação completa, mas o índice ainda está abaixo do ponto de partida. Quando o valor de partida é muito baixo, é fácil ter taxas altas.`},
    {t:'decide',id:'q4',ensina:['p4b','c1'],label:'Decide',q:'O PMI da Zona Euro fica em 47,5 pontos. O que sugere?',o:['Que a atividade das empresas está a contrair, segundo o inquérito','Que a economia está em forte expansão','Que o PMI está estragado e não diz nada'],c:0,why:'Abaixo de 50 sinaliza contração, na ótica dos gestores inquiridos. Não é um dado oficial nem decide, por si só, uma recessão, mas costuma ser um aviso antecipado.'},
    {t:'decide',id:'q5',ensina:['u1','p5'],label:'Decide',q:'Um indicador desceu 10% num ano e no ano seguinte subiu 10%. Está de volta ao valor de partida?',o:['Sim, +10% compensa −10%','Não: ficou 1% abaixo do valor inicial','Sim, porque os dois números são iguais'],c:1,why:'100 × 0,9 × 1,1 = 99. As percentagens de subida e de descida incidem sobre bases diferentes, e é por isso que se diz que a recuperação é sempre maior do que a queda.'},
    {t:'h',id:'h7',x:'Um caso real: Portugal entre 2011 e 2014'},
    {t:'p',id:'p6',x:'Portugal esteve sob um programa de assistência financeira entre 2011 e 2014, no seguimento da crise da dívida na Zona Euro. Nesses anos, o PIB recuou em vários períodos seguidos e a taxa de desemprego chegou a máximos acima de 15%, sobretudo nos jovens, antes de começar a descer nos anos seguintes. Quem olhava só para o PIB podia achar que a pior fase já tinha passado quando o desemprego, que é um indicador atrasado, ainda continuava a subir. A lição: lê vários indicadores, e lembra-te de que uns avisam antes, outros só confirmam depois.'},
    {t:'h',id:'h8',x:'Os erros que mais custam'},
    {t:'ul',id:'u2',x:[
      'Reagir ao número em vez de reagir à surpresa face ao esperado.',
      'Confundir variação em cadeia com variação homóloga.',
      'Tratar o PIB nominal como se fosse real, ou ignorar a inflação nas comparações.',
      'Tirar conclusões de um único mês: os dados oscilam e são revistos.',
      'Achar que um bom número económico é sempre bom para a bolsa (pode levar o banco central a subir taxas).']},
    {t:'erro',id:'q6',ensina:['p1','p1b','p4b','c1'],label:'Encontra o erro',q:'Uma destas frases sobre indicadores está errada. Qual?',o:['O PIB real é o PIB descontado da inflação','O PMI é um dado oficial publicado pelo INE','O desemprego é um indicador atrasado','Uma variação homóloga compara com o mesmo período do ano anterior'],c:1,why:'O PMI é um inquérito feito por uma empresa privada (S&P Global). Os dados oficiais de Portugal vêm do INE e os da UE do Eurostat.'},
    {t:'h',id:'h9',x:'Em Portugal'},
    {t:'p',id:'p7',x:'Os dados oficiais de Portugal estão no site do INE (inflação, PIB, emprego e desemprego) e no Banco de Portugal (projeções, estatísticas). Os da Zona Euro estão no Eurostat e no BCE. Todos têm calendário de divulgação público, e a vista Calendário deste site mostra os principais. Os valores atuais não os escrevi aqui para não ficarem desatualizados: consulta sempre a fonte. Para perceber como cada indicador afeta o que investes, vê os temas «Bancos centrais e taxas de juro», «Ciclos económicos e recessões» e «Como ler o calendário económico».'},
    {t:'h',id:'h10',x:'Em poucas palavras'},
    {t:'ul',id:'u3',x:[
      'PIB mede o que a economia produz; o que interessa é o PIB real (sem a inflação).',
      'A taxa de desemprego divide os desempregados pela população ativa e pode descer sem criar emprego.',
      'O PMI é um inquérito privado: acima de 50, expansão; abaixo, contração. É adiantado.',
      'Em Portugal publica o INE; na UE, o Eurostat; o BCE e o Banco de Portugal publicam decisões e projeções.',
      'Lê vários indicadores: uns adiantam-se, outros atrasam-se; e repara na surpresa, nas revisões e no efeito de base.']}
  ], src:[
    {l:'INE: Instituto Nacional de Estatística',u:'https://www.ine.pt'},
    {l:'Eurostat: indicadores do euro',u:'https://ec.europa.eu/eurostat/news/euro-indicators'},
    {l:'BCE: Banco Central Europeu',u:'https://www.ecb.europa.eu'}] }
,
{ id:'ciclos', topic:'mercados', o:7, title:'Ciclos económicos e recessões', mins:7,
  lead:'A economia não cresce em linha reta: alterna fases de expansão e de abrandamento. Perceber o ciclo ajuda a não entrar em pânico a cada queda e a perceber porque é que a bolsa e as notícias nem sempre dizem o mesmo.',
  blocks:[
    {t:'h',id:'h0',x:'As marés e as estações'},
    {t:'p',id:'p0',x:'O mar sobe e desce todos os dias; o ano passa por estações. Nenhuma maré dura para sempre e nenhum inverno é permanente. A economia tem ritmos parecidos, só que irregulares: períodos longos de crescimento, seguidos de abrandamentos, e depois nova recuperação. Quem se lembra de que o inverno acaba não vende o casaco à primeira geada.'},
    {t:'p',id:'p1',x:'Um ciclo tem quatro fases: <b>expansão</b> (a economia cresce, o emprego sobe), <b>pico</b>, <b>contração</b> (a atividade recua) e <b>vale</b>, a partir do qual recomeça a recuperação. Uma <b>recessão</b> é uma contração prolongada e generalizada. Como regra prática, fala-se em recessão quando o PIB cai durante dois trimestres seguidos.'},
    {t:'p',id:'p1b',x:'Na prática, a regra dos dois trimestres é uma convenção de jornal. Quem «oficializa» as recessões são comités de especialistas (nos EUA, o NBER; na Zona Euro, o comité de datação do CEPR), que olham para vários indicadores (emprego, rendimento, produção) e só anunciam a data meses depois de a recessão ter começado. Por isso, quando a recessão é declarada, o pior pode já ter passado.'},
    {t:'h',id:'h1',x:'O que faz o ciclo rodar'},
    {t:'cmp',id:'c1',head:['Fase','Economia','Inflação e juros','Mercados (tendência geral)'],rows:[
      ['Expansão','Cresce, o emprego sobe, as empresas investem','Inflação tende a subir; o banco central sobe as taxas','Ações tendem a subir; cíclicos vão bem'],
      ['Pico','Crescimento muito forte, risco de excessos','Taxas altas, crédito mais caro','Valorizações elevadas; os preços já descontam muito'],
      ['Contração','Atividade recua, desemprego sobe','Inflação abranda; o banco central pára ou desce taxas','Ações caem; defensivos aguentam melhor'],
      ['Vale','Fundo da atividade, confiança baixa','Taxas baixas, estímulo da política económica','Ações podem começar a subir antes de a economia melhorar']],
      cap:'Descrição estilizada. Cada ciclo é diferente: a duração, a causa e a reação dos mercados variam.'},
    {t:'p',id:'p1c',x:'O ciclo alimenta-se a si próprio. Quando a economia vai bem, as empresas investem e as pessoas gastam, o crédito cresce e os preços sobem. O banco central responde subindo os juros. Mais tarde, o crédito encarece, o consumo e o investimento abrandam, e a economia arrefece. Então o banco central baixa as taxas, o crédito volta a ser barato e o ciclo recomeça. Choques inesperados (uma crise financeira, uma pandemia, uma guerra) podem encurtar ou aprofundar as fases.'},
    {t:'h',id:'h2',x:'Os mercados olham para a frente'},
    {t:'p',id:'p2',x:'Os mercados <b>antecipam</b>: costumam cair antes de a recessão ser oficial e subir antes de a economia melhorar. Por isso, tentar sair e entrar na altura certa é muito difícil, e quem falha as melhores subidas paga caro.'},
    {t:'decide',id:'q1',ensina:['p2'],label:'Decide',q:'As notícias dizem que a economia entrou em recessão e a bolsa já caiu 25%. O que costuma acontecer a seguir?',o:['A bolsa só pode continuar a descer até a recessão acabar','Os preços ficam parados até haver notícias positivas','A bolsa pode já estar a antecipar a recuperação, porque os mercados olham para a frente'],c:2,why:'Os mercados reagem às expectativas e costumam recuperar antes de os dados económicos melhorarem. Não é garantido, mas explica por que prever o momento certo é tão difícil.'},
    {t:'h',id:'h3',x:'Mercado em alta e em baixa'},
    {t:'p',id:'p3',x:'Convenciona-se chamar <b>mercado em baixa</b> (bear market) a uma queda de 20% ou mais desde o máximo, e <b>mercado em alta</b> (bull market) à fase de subida prolongada. Quedas fortes acontecem de tempos a tempos, e quem investe a longo prazo tem de contar com elas.'},
    {t:'w',id:'w1',w:'calc',c:'drawdown'},
    {t:'fazve',id:'q2',ensina:['p3','w1'],q:'Um mercado cai 20% desde o máximo. Quanto tem de subir, em %, para voltar ao máximo anterior?',unit:'%',answer:_c('drawdown',{val:1000,q:20})[1],tol:.02,why:'Subir 25%: 100 caiu para 80, e 80 × 1,25 = 100. A subida necessária é sempre maior do que a queda.'},
    {t:'h',id:'h4',x:'Quanto tempo demora a recuperar?'},
    {t:'p',id:'p4',x:'A resposta depende do que o mercado faz depois. Se, a seguir à queda, o mercado voltasse a subir à taxa de 7% ao ano (valor de exemplo, não é uma previsão), estes seriam os prazos para recuperar:'},
    {t:'cmp',id:'c2',head:['Queda desde o máximo','Subida necessária','Anos para recuperar (a 7% ao ano)'],rows:[10,20,30,50].map(q=>[q+'%',_mer_pt(q/(100-q)*100,1)+'%',_mer_pt(-Math.log(1-q/100)/Math.log(1.07),1)+' anos']),cap:'Contas ilustrativas: -ln(1 − queda) ÷ ln(1,07). Na realidade as recuperações são irregulares: podem ser muito mais rápidas ou mais lentas.'},
    {t:'p',id:'p4b',x:'Quedas pequenas recuperam depressa; quedas grandes demoram anos. Por isso a diversificação, o horizonte temporal e não vender em pânico contam tanto (temas «Objetivos e horizonte temporal» e «Quedas máximas (drawdown)»).'},
    {t:'h',id:'h5',x:'Dois casos reais: 2008 e 2020'},
    {t:'p',id:'p5',x:'A <b>crise de 2008</b> começou com crédito à habitação barato e demasiado fácil nos EUA. Quando os preços das casas caíram e muita gente deixou de pagar, os bancos acumularam perdas, o sistema financeiro ficou à beira do colapso (a falência do banco Lehman Brothers foi o momento simbólico) e o mundo entrou numa recessão profunda, a «Grande Recessão». As bolsas caíram para cerca de metade do máximo anterior. A recuperação demorou anos e foi ajudada por taxas muito baixas e por programas dos bancos centrais.'},
    {t:'p',id:'p5b',x:'Em <b>2020</b>, a pandemia parou a economia de forma súbita. A recessão foi uma das mais profundas, mas das mais curtas: governos e bancos centrais agiram depressa e as bolsas recuperaram em meses, muito antes de a economia ter recuperado. Os dois episódios mostram o mesmo: as bolsas não seguem a economia à letra, antecipam-na, e o ciclo pode ser longo (2008) ou curto (2020), conforme a causa e a resposta.'},
    {t:'h',id:'h6',x:'Os erros que mais custam'},
    {t:'ul',id:'u1',x:[
      'Tentar sair antes da recessão e voltar antes da recuperação: é preciso acertar duas vezes, e as melhores subidas costumam vir logo a seguir às piores quedas.',
      'Achar que a bolsa só recupera quando as notícias melhorarem: quando melhoram, o preço já subiu.',
      'Julgar um ciclo pelo anterior: cada um tem causas e respostas diferentes.',
      'Concentrar tudo em cíclicos no pico, ou em defensivos no vale, quando o momento já passou.',
      'Confundir uma correção normal (10 a 20%) com o fim do mundo.']},
    {t:'erro',id:'q3',ensina:['p1','p1b','p2','c1'],label:'Encontra o erro',q:'Uma destas frases sobre ciclos está errada. Qual?',o:['As recessões são sempre previstas com antecedência exata pelos mercados','Uma recessão é uma contração prolongada e generalizada da economia','Os mercados costumam antecipar a recuperação da economia','Quem declara oficialmente uma recessão costuma fazê-lo meses depois do início'],c:0,why:'Os mercados antecipam, mas não acertam sempre nem na data nem no tamanho. Prever o momento exato continua a ser muito difícil, mesmo para profissionais.'},
    {t:'h',id:'h7',x:'Em Portugal'},
    {t:'p',id:'p6',x:'Portugal é uma economia pequena e aberta, muito ligada à Europa: exportações, turismo e investimento estrangeiro pesam muito. O ciclo português costuma seguir o europeu e é afetado quando há choques no turismo, no crédito ou nas exportações. Para acompanhar o ciclo, consulta o INE (PIB e emprego), o Banco de Portugal (projeções) e o Eurostat; os temas «Indicadores macro: PIB, desemprego, inflação, PMI» e «Curva de rendimentos e o que diz sobre a economia» explicam como ler os sinais.'},
    {t:'h',id:'h8',x:'Em poucas palavras'},
    {t:'ul',id:'u2',x:[
      'O ciclo tem expansão, pico, contração e vale; uma recessão é uma contração prolongada e generalizada.',
      'A «regra dos dois trimestres» é uma convenção; as datas oficiais vêm de comités, meses depois.',
      'Os mercados antecipam e costumam recuperar antes de a economia melhorar.',
      'Mercado em baixa: queda de 20% ou mais desde o máximo; recuperar exige uma subida maior do que a queda.',
      'Quedas fortes aparecem de tempos a tempos: quem investe a longo prazo planeia para elas.']}
  ], src:[] }
,
{ id:'curva-rendimentos', topic:'mercados', o:8, title:'Curva de rendimentos e o que diz sobre a economia', mins:8,
  lead:'A curva de rendimentos junta, num só gráfico, o que os mercados pagam por emprestar dinheiro a um Estado a 3 meses, a 2 anos, a 10 anos ou a 30 anos. A forma dessa curva é uma das leituras mais seguidas sobre o futuro da economia e das taxas de juro.',
  blocks:[
    {t:'h',id:'h0',x:'O preço de emprestar por mais tempo'},
    {t:'p',id:'p0',x:'Se emprestasses dinheiro a um amigo, pedirias mais juros por um empréstimo a 10 anos do que por um a 10 dias: ao fim de tanto tempo pode acontecer muita coisa (inflação, imprevistos, ele não pagar). Os Estados são os devedores mais seguros do mercado, mas a lógica mantém-se: emprestar por mais tempo costuma pagar mais. A <b>curva de rendimentos</b> mostra isso: no eixo horizontal o prazo (do empréstimo), no vertical a taxa (rendimento) que o mercado exige.'},
    {t:'h',id:'h1',x:'Obrigações em dois minutos'},
    {t:'p',id:'p1',x:'Uma <b>obrigação</b> é um empréstimo transformado em título: o Estado (ou uma empresa) recebe dinheiro e promete devolvê-lo numa data (o <b>vencimento</b>), pagando juros pelo caminho (os <b>cupões</b>). O <b>rendimento</b> (yield) é a taxa anual que ganharias se comprasses a obrigação ao preço de hoje e a guardasses até ao fim. Há uma regra que convém decorar: <b>quando o rendimento sobe, o preço da obrigação desce, e vice-versa</b>. As obrigações antigas valem menos quando aparecem novas a pagar mais.'},
    {t:'p',id:'p1b',x:'Quanto mais longo o prazo, mais o preço mexe com uma mesma variação de taxas. Uma obrigação sem cupão que paga 100 € no fim, e cujo rendimento sobe de 3% para 4%, vale:'},
    {t:'cmp',id:'c1',head:['Prazo','Preço com rendimento de 3%','Preço com rendimento de 4%','Variação do preço'],rows:[2,5,10,30].map(n=>[n+' anos',_mer_e2(_mer_zc(3,n)),_mer_e2(_mer_zc(4,n)),_mer_pt((_mer_zc(4,n)/_mer_zc(3,n)-1)*100,1)+'%']),cap:'Obrigações sem cupão, valor de reembolso de 100 €, valores de exemplo. Quanto mais longo o prazo, maior a perda para a mesma subida de 1 ponto.'},
    {t:'fazve',id:'q1',ensina:['p1','p1b','c1'],q:'Uma obrigação a 10 anos sem cupão vale hoje cerca de 74,41 € com um rendimento de 3%. Se o rendimento subir para 4%, quanto passa a valer, em €?',unit:'€',answer:_mer_zc(4,10),tol:.005,why:`100 ÷ 1,04¹⁰ ≈ ${_mer_e2(_mer_zc(4,10))}. O preço caiu cerca de ${_mer_pt((1-_mer_zc(4,10)/_mer_zc(3,10))*100,1)}%, só porque o rendimento subiu um ponto.`},
    {t:'h',id:'h2',x:'As formas da curva'},
    {t:'cmp',id:'c2',head:['Prazo','Curva normal','Curva plana','Curva invertida'],rows:_mer_curvas.rows.map(r=>[r.n,...r.v.map(x=>_mer_pt(x,2)+'%')]).concat([['Diferença 10 anos − 2 anos',..._mer_curvas.dif.map(x=>_mer_pt(x,2)+' pp')]]),cap:'Valores de exemplo, não são taxas reais. «pp» = pontos percentuais.'},
    {t:'ul',id:'u1',x:[
      '<b>Normal</b>: sobe com o prazo. Os mercados esperam crescimento e inflação moderada e pedem mais por emprestar a mais tempo.',
      '<b>Plana</b>: todos os prazos pagam parecido. Costuma aparecer na transição entre fases, quando o mercado está indeciso.',
      '<b>Invertida</b>: as taxas curtas estão acima das longas. O mercado espera que o banco central tenha de <b>baixar</b> as taxas no futuro, normalmente porque a economia vai abrandar.']},
    {t:'h',id:'h3',x:'O que mexe em cada ponta'},
    {t:'p',id:'p2',x:'A ponta <b>curta</b> da curva (até 2 anos) segue de perto as taxas do banco central e o que o mercado espera que ele faça nas próximas reuniões (tema «Bancos centrais e taxas de juro»). A ponta <b>longa</b> (10 anos ou mais) reflete as expectativas sobre o crescimento e a inflação a longo prazo, mais um <b>prémio de prazo</b>: um extra que os investidores pedem por correrem o risco de ficar presos tanto tempo.'},
    {t:'p',id:'p2b',x:`Dá para ver como uma curva inverte só com expectativas. Se hoje o rendimento a 1 ano é 4% e o mercado espera que daqui a 1 ano as taxas curtas caiam para 2%, então dois anos devem render, por ano, aproximadamente ${_mer_pt((Math.sqrt(1.04*1.02)-1)*100,2)}%: a média dos 4% e dos 2% (em juros compostos). A taxa a 2 anos fica abaixo da taxa a 1 ano, e a curva inverte-se. Sem ninguém «prever» uma recessão, apenas por esperar cortes de taxas.`},
    {t:'fazve',id:'q2',ensina:['c2','u1'],q:'Se o rendimento a 10 anos é 3,20% e o rendimento a 2 anos é 3,60%, qual é a diferença 10 anos − 2 anos, em pontos percentuais? (Um valor negativo indica curva invertida.)',unit:'pp',answer:-0.4,tol:.1,why:'3,20 − 3,60 = −0,40 pontos percentuais. A diferença é negativa, por isso a curva está invertida neste troço: as taxas curtas estão acima das longas.'},
    {t:'h',id:'h4',x:'O que a curva diz (e o que não diz) sobre a economia'},
    {t:'p',id:'p3',x:'A curva invertida é um dos sinais mais citados de que uma recessão pode estar a caminho: nos EUA, as recessões das últimas décadas foram quase sempre precedidas por uma inversão. Mas há três avisos. Primeiro, a antecedência varia muito, de alguns meses a mais de um ano. Segundo, houve inversões sem recessão a seguir, e recessões causadas por choques que a curva não podia prever. Terceiro, a curva é um indicador do <b>sentimento do mercado de obrigações</b>, não uma lei da economia.'},
    {t:'p',id:'p3b',x:'Quando as taxas curtas acabam por descer (o banco central corta), a curva volta a ficar normal. Mas isso costuma acontecer já com a economia fraca: a «normalização» da curva não é necessariamente boa notícia.'},
    {t:'decide',id:'q3',ensina:['p2','p2b','p3'],label:'Decide',q:'A curva de rendimentos inverteu-se: os rendimentos a 2 anos estão acima dos de 10 anos. Como é que isso costuma ser interpretado?',o:['Como garantia de que haverá uma recessão no mês seguinte','Como sinal de que o mercado espera taxas mais baixas no futuro, muitas vezes por esperar abrandamento económico','Como prova de que o banco central vai subir as taxas sem parar','Como um erro estatístico sem significado'],c:1,why:'A inversão reflete expectativas de taxas mais baixas no futuro, o que costuma ligar-se a um abrandamento esperado. Não é uma garantia nem tem data marcada.'},
    {t:'h',id:'h5',x:'Zona Euro: não há uma só curva'},
    {t:'p',id:'p4',x:'Nos EUA, a curva de referência é a das obrigações do Tesouro americano. Na Zona Euro, cada país emite as suas obrigações (Alemanha, França, Itália, Portugal) e por isso há várias curvas. A Alemanha é a referência de «ativo seguro» e a diferença entre o rendimento de um país e o alemão chama-se <b>spread</b> (ou prémio de risco). O BCE publica diariamente uma curva da Zona Euro estimada a partir das obrigações com melhor rating (AAA), com modelo de Svensson (verificado em 17/11/2026 no portal de dados do BCE).'},
    {t:'p',id:'p4b',x:`Se a obrigação portuguesa a 10 anos rende 3,20% e a alemã 2,60%, o spread é de ${_mer_pt(3.2-2.6,2)} pontos percentuais (60 pontos base). Quanto maior o spread, mais risco o mercado vê no país. Em 2011 e 2012, no auge da crise da dívida da Zona Euro, os juros da dívida portuguesa a 10 anos subiram acima de 10%, e o spread face à Alemanha tornou-se enorme, o que mostra a rapidez com que a confiança pode mudar. Os valores deste exemplo são inventados; os reais encontram-se no IGCP e no BCE.`},
    {t:'h',id:'h6',x:'Um caso real: 2006, 2007 e 2019'},
    {t:'p',id:'p5',x:'Nos EUA, a curva inverteu-se em 2006 e manteve-se assim em 2007; a recessão começou no fim de 2007 e transformou-se na crise de 2008. Foi um sinal que avisou com muita antecedência. Em 2019, a curva americana voltou a inverter-se, e em 2020 houve uma recessão curta e violenta, mas causada pela pandemia, que ninguém tinha como prever em 2019. O sinal foi «certo» no resultado, mas por razões que nada tinham que ver com ele. O que isto ensina é que a curva dá pistas, não certezas.'},
    {t:'h',id:'h7',x:'Os erros que mais custam'},
    {t:'ul',id:'u2',x:[
      'Tratar a inversão como uma previsão com data: pode demorar mais de um ano.',
      'Esquecer que existe mais de uma curva na Zona Euro e comparar rendimentos de países diferentes como se fossem iguais.',
      'Comparar uma obrigação a longo prazo com um depósito a 1 ano, sem ter em conta o risco de preço se venderes antes do vencimento.',
      'Pensar que obrigações «não perdem»: quando os rendimentos sobem, os preços descem, sobretudo nas mais longas.',
      'Tentar mudar a carteira por causa de um sinal da curva sem considerar o resto do contexto.']},
    {t:'erro',id:'q4',ensina:['p1','c1','u1','p3'],label:'Encontra o erro',q:'Uma destas frases sobre a curva de rendimentos está errada. Qual?',o:['Quando o rendimento de uma obrigação sobe, o preço dela desce','Numa curva invertida, as taxas curtas estão acima das longas','A curva invertida garante que haverá uma recessão dentro de seis meses','A ponta curta da curva segue sobretudo as taxas do banco central'],c:2,why:'A inversão é um sinal, não uma garantia. A antecedência é muito variável e já houve falsos alarmes.'},
    {t:'h',id:'h8',x:'Em Portugal'},
    {t:'p',id:'p6',x:'Em Portugal, quem emite dívida do Estado é o IGCP (Agência de Gestão da Tesouraria e da Dívida Pública), através das Obrigações do Tesouro (OT) e dos produtos de poupança (tema «Certificados de Aforro e do Tesouro»). A curva afeta-te de várias formas: a ponta curta determina a Euribor e, com ela, a prestação dos créditos à habitação a taxa variável; a longa influencia as taxas de créditos a taxa fixa e o preço das obrigações em carteira (tema «Obrigações»). Os dados da curva da Zona Euro estão no portal de dados do BCE.'},
    {t:'h',id:'h9',x:'Em poucas palavras'},
    {t:'ul',id:'u3',x:[
      'A curva de rendimentos mostra a taxa que o mercado exige por prazo: normal (sobe), plana ou invertida (as curtas acima das longas).',
      'Rendimento e preço de uma obrigação mexem em sentido contrário, e mais nas obrigações longas.',
      'A ponta curta segue o banco central; a longa reflete crescimento, inflação e prémio de prazo.',
      'A inversão sinaliza que o mercado espera cortes de taxas, muitas vezes por esperar abrandamento: é um sinal, não uma garantia.',
      'Na Zona Euro há várias curvas; o spread face à Alemanha mede o risco que o mercado vê em cada país.']}
  ], src:[
    {l:'BCE: curva de rendimentos AAA da Zona Euro',u:'https://data.ecb.europa.eu/data/data-categories/financial-markets-and-interest-rates/euro-area-yield-curves/aaa-rated-government-bonds-yield-curve/spot-curve'},
    {l:'IGCP: Agência de Gestão da Tesouraria e da Dívida Pública',u:'https://www.igcp.pt'}] }
,
{ id:'cambios', topic:'mercados', o:9, title:'Câmbios: porque o euro e o dólar contam', mins:7,
  lead:'Quando compras ativos noutra moeda, ganhas ou perdes não só pelo que o ativo faz mas também pelo que a moeda faz contra o euro. É um efeito que pode ser tão grande como o do próprio investimento.',
  blocks:[
    {t:'h',id:'h0',x:'A casa de câmbios do aeroporto'},
    {t:'p',id:'p0',x:'Quem viajou para fora da Zona Euro conhece a sensação: um ano a viagem sai barata, noutro ano a mesma viagem custa muito mais, sem que nada tenha mudado a não ser a taxa de câmbio. O preço de uma moeda em termos de outra é um preço como outro qualquer: sobe e desce consoante a procura e a oferta. E se alguma vez deixares dinheiro em dólares, libras ou francos suíços, o que vales em euros muda com esse preço.'},
    {t:'p',id:'p1',x:'Uma taxa de câmbio diz quantas unidades de uma moeda compras com outra. Se o <b>EUR/USD</b> está a 1,10, um euro compra 1,10 dólares. Se o EUR/USD <b>sobe</b>, o euro fortalece-se: cada euro compra mais dólares, e os ativos em dólares valem menos em euros.'},
    {t:'p',id:'p1b',x:'Lê-se sempre assim: no par <b>EUR/USD</b>, a primeira moeda (EUR) é a <b>base</b> e a segunda (USD) é a <b>cotada</b>. O número diz quanto custa uma unidade da base em unidades da cotada. Se o par se inverte (USD/EUR), o número é o inverso: 1 ÷ 1,10 ≈ 0,91 euros por dólar.'},
    {t:'h',id:'h1',x:'O efeito no teu investimento'},
    {t:'p',id:'p2',x:'Imagina um ativo americano que sobe 10% em dólares. Se o dólar perder 5% contra o euro no mesmo período, o ganho em euros é bastante menor: <b>1,10 × 0,95 − 1 ≈ 4,5%</b>. Em sentido contrário, um dólar mais forte aumenta o teu ganho. A isto chama-se <b>risco cambial</b>.'},
    {t:'cmp',id:'c1',head:['Se o dólar, face ao euro...','Ativo sobe 10% em dólares: ganho em euros','Ativo cai 10% em dólares: resultado em euros'],rows:[-10,-5,0,5,10].map(x=>[(x>0?'sobe ':x<0?'cai ':'fica igual')+(x?Math.abs(x)+'%':''),_mer_pt((1.1*(1+x/100)-1)*100,1)+'%',_mer_pt((0.9*(1+x/100)-1)*100,1)+'%']),cap:'«Dólar cai 5%» quer dizer que cada dólar vale menos 5% em euros. Valores de exemplo.'},
    {t:'fazve',id:'q1',ensina:['p2','c1'],q:'Um ativo em dólares sobe 10%, mas o dólar perde 5% contra o euro. Quanto ganhas em euros, em %?',unit:'%',answer:(1.1*.95-1)*100,tol:.05,why:'1,10 × 0,95 = 1,045, ou seja, +4,5%. Metade do ganho foi comida pela moeda.'},
    {t:'decide',id:'q2',ensina:['p1','p2'],label:'Decide',q:'Tens um ativo em dólares. O euro fortalece-se contra o dólar. O que acontece ao valor do ativo em euros?',o:['Sobe, porque o euro está mais forte','Não muda, porque o ativo continua igual','Desce, porque cada dólar compra menos euros'],c:2,why:'Com um euro mais forte, cada dólar vale menos euros. O ativo pode estar igual em dólares e valer menos em euros.'},
    {t:'h',id:'h2',x:'O que faz as moedas mexerem'},
    {t:'ul',id:'u1',x:[
      '<b>Diferença de taxas de juro</b>: uma moeda com taxas mais altas tende a atrair capital e a fortalecer-se (o capital vai para onde paga mais).',
      '<b>Inflação relativa</b>: um país com inflação mais alta vê, a longo prazo, a sua moeda perder valor face a outras.',
      '<b>Crescimento e confiança</b>: economias fortes e estáveis atraem investimento.',
      '<b>Balança comercial</b>: quem exporta mais do que importa tende a ter procura pela sua moeda.',
      '<b>Fugas para a segurança</b>: em crises, o dinheiro costuma procurar moedas consideradas refúgio (o dólar, o franco suíço, o iene).',
      '<b>Decisões dos bancos centrais</b>: uma subida de taxas, ou a promessa dela, mexe com a moeda de imediato.']},
    {t:'h',id:'h3',x:'Cobertura cambial: um seguro com preço'},
    {t:'p',id:'p3',x:'Muitos ETFs que se compram em Portugal vêm em euros mas investem em ativos noutras moedas (por exemplo, o S&P 500 em dólares). O risco cambial continua lá dentro, a menos que o ETF seja «com cobertura cambial» (hedged), o que costuma ter custo.'},
    {t:'p',id:'p3b',x:`Esse custo vem sobretudo da diferença entre as taxas de juro das duas moedas. Se um investidor em euros quer eliminar o risco do dólar e as taxas curtas em dólares são 4% e em euros 2%, a cobertura custa, aproximadamente, a diferença: ${_mer_pt(4-2,1)} pontos percentuais por ano (valores de exemplo; mudam). Se as taxas forem iguais, a cobertura custa quase nada. Por isso a cobertura não é uma escolha «grátis»: troca um risco (a moeda) por um custo certo. Ter ou não cobertura depende do prazo e do que tentas proteger.`},
    {t:'cmp',id:'c2',head:['','Sem cobertura','Com cobertura'],rows:[
      ['Risco cambial','Sim: o ganho ou perda em euros mistura ativo e moeda','Reduzido: só fica o desempenho do ativo'],
      ['Custo','Nenhum custo extra de cobertura','Custo de cobertura, ligado à diferença de taxas de juro'],
      ['Em crises','O dólar tem fortalecido em várias crises, o que amorteceu quedas para quem investe a partir do euro (não é regra)','Esse amortecimento perde-se'],
      ['Quando se usa','Pode ser aceitável se o objetivo é de longo prazo e aceitas a oscilação da moeda','Mais usada em prazos curtos ou em obrigações, onde o câmbio pode pesar mais do que o retorno do ativo']],
      cap:'Resumo geral. Cada produto tem a sua política: confirma sempre no documento do ETF (KID) se é «hedged» ou não.'},
    {t:'h',id:'h4',x:'Um caso real: o euro, de 1999 a 2008'},
    {t:'p',id:'p4',x:'O euro nasceu em 1999 perto de 1,17 dólares. Nos dois anos seguintes caiu abaixo dos 0,90, o que fez muita gente duvidar da nova moeda. Depois subiu de forma contínua e chegou perto dos 1,60 dólares em 2008, antes de recuar na crise financeira. Entre o mínimo e o máximo, o euro quase duplicou de valor face ao dólar em menos de uma década. Quem tinha investido em ativos em dólares a partir do euro teve resultados muito diferentes conforme o momento, mesmo com ativos que se portaram de forma parecida em dólares.'},
    {t:'p',id:'p4b',x:'A lição é que as moedas podem oscilar muito durante anos. Não há um nível «certo» do câmbio, e prever o seu movimento é tão difícil como prever o das ações. O que podes fazer é perceber o risco e decidir, com consciência, se o queres.'},
    {t:'h',id:'h5',x:'Os erros que mais custam'},
    {t:'ul',id:'u2',x:[
      'Ignorar o câmbio ao avaliar um investimento fora da Zona Euro: o retorno em euros pode ser muito diferente do retorno em dólares.',
      'Achar que «ETF em euros» é o mesmo que «sem risco cambial»: depende do que o ETF compra.',
      'Comparar o retorno de um ETF coberto com um não coberto sem ver o custo da cobertura.',
      'Converter moeda várias vezes (ida e volta) com comissões altas.',
      'Tentar prever o câmbio para ganhar dinheiro: é uma das apostas mais difíceis.']},
    {t:'erro',id:'q3',ensina:['p1','p1b','p2','c1'],label:'Encontra o erro',q:'Uma destas frases sobre câmbios está errada. Qual?',o:['Se o EUR/USD sobe, o euro fortalece-se face ao dólar','Um ativo americano que sobe 10% em dólares dá sempre 10% em euros','Um ETF com cobertura cambial tem, em regra, um custo adicional','Um dólar mais fraco reduz o ganho em euros de um ativo em dólares'],c:1,why:'O ganho em euros depende também do que o dólar fez contra o euro: 10% em dólares pode dar mais ou menos de 10% em euros.'},
    {t:'h',id:'h6',x:'Em Portugal'},
    {t:'p',id:'p5',x:'Portugal faz parte da Zona Euro, por isso, para quem compra ativos em euros (as ações da Euronext Lisboa, os ETFs em euros que investem na Europa), não há risco cambial direto. Há risco quando compras ativos em dólares, em libras ou em francos suíços, ou ETFs que investem lá fora. O BCE publica diariamente taxas de câmbio de referência do euro (verificado em 17/11/2026 no site do BCE; são indicativas e não servem para negociar), e as corretoras cobram comissões de conversão que variam muito: compara antes de converter dinheiro. Vê também o tema «Risco cambial, de liquidez e de inflação».'},
    {t:'note',id:'n1',pending:true,x:'Por confirmar na AT: como se tratam fiscalmente os ganhos e perdas cambiais ao vender ativos em moeda estrangeira (por exemplo, se o cálculo da mais-valia usa os preços em euros à data da compra e da venda). Não escrevi regras de memória: vê os temas «Mais-valias: quanto imposto pagas ao vender» e «Declarar no IRS: Modelo 3, anexos G e J».'},
    {t:'h',id:'h7',x:'Em poucas palavras'},
    {t:'ul',id:'u3',x:[
      'EUR/USD a 1,10: um euro compra 1,10 dólares. Se sobe, o euro fortalece-se.',
      'O ganho em euros de um ativo em dólares é (1 + retorno em dólares) × (1 + variação do dólar) − 1.',
      'As moedas mexem com as taxas de juro, a inflação relativa, o crescimento e a confiança, e podem oscilar muito durante anos.',
      'A cobertura cambial reduz o risco, mas custa aproximadamente a diferença de taxas de juro entre as moedas.',
      'Em Portugal, o risco cambial só existe quando os ativos não são em euros ou investem fora da Zona Euro.']}
  ], src:[
    {l:'BCE: taxas de câmbio de referência do euro',u:'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/index.en.html'}] }
,
{ id:'calendario-economico', topic:'mercados', o:10, title:'Como ler o calendário económico', mins:7,
  lead:'O calendário económico lista os dados e decisões que mexem com os mercados e a hora a que saem. Saber lê-lo evita surpresas e ajuda a perceber as oscilações de um dia.',
  blocks:[
    {t:'h',id:'h0',x:'A agenda dos jogos'},
    {t:'p',id:'p0',x:'Antes de um jogo de futebol sabes quem joga, a que horas e quem é o favorito. O que faz do jogo uma notícia não é o resultado em si, mas se o favorito perdeu ou ganhou. O calendário económico funciona assim: lista os «jogos» da semana (inflação, emprego, decisões de taxas), com a hora, e com o «resultado esperado». O que mexe com o mercado é o desvio entre o esperado e o que saiu.'},
    {t:'p',id:'p1',x:'Cada linha tem a hora, o país, o <b>indicador</b>, a <b>previsão</b> dos analistas, o valor <b>anterior</b> e, quando sai, o valor <b>real</b>. A reação do mercado depende menos do número em si e mais da <b>surpresa</b>: a diferença entre o que saiu e o que se esperava.'},
    {t:'h',id:'h1',x:'Linha a linha'},
    {t:'cmp',id:'c1',head:['Coluna','O que significa','Como usar'],rows:[
      ['Hora','Momento da divulgação; atenção ao fuso horário','Convém estar atento: muitos dados saem a horas certas e o preço mexe logo'],
      ['País ou região','De onde vem o dado','Dados da Zona Euro pesam mais para o euro; dados dos EUA pesam em todo o mundo'],
      ['Indicador','O que se mede (inflação, PIB, emprego...)','Vê o tema «Indicadores macro: PIB, desemprego, inflação, PMI»'],
      ['Impacto','Importância estimada (baixo, médio, alto)','Dá prioridade aos de impacto alto'],
      ['Previsão (consenso)','Média das estimativas dos analistas','É a referência para medir a surpresa'],
      ['Anterior','Valor da divulgação anterior (pode ter sido revisto)','Mostra a tendência'],
      ['Real','O número que saiu','A diferença para a previsão é o que importa']],
      cap:'A «previsão» é uma média: se for muito diferente de outras, o mercado ajusta-se logo.'},
    {t:'h',id:'h2',x:'Que tipos de eventos aparecem'},
    {t:'cmp',id:'c2',head:['Indicador','O que diz','Porque mexe com os mercados'],rows:[
      ['Inflação (IPC)','Quanto subiram os preços','Influencia as decisões sobre taxas de juro'],
      ['PIB','Quanto cresceu a economia','Mostra a saúde da economia e dos lucros'],
      ['Emprego / desemprego','Quanta gente trabalha','Emprego forte sustenta o consumo, mas pode alimentar inflação'],
      ['Decisão de taxas','O que o banco central fez ou sinalizou','Muda o custo do dinheiro para todos'],
      ['Resultados de empresas','Lucros e vendas','Mexem diretamente com o preço da ação']]},
    {t:'p',id:'p1b',x:'Há ainda os discursos de responsáveis dos bancos centrais, os leilões de dívida pública, as reuniões de política monetária (com conferência de imprensa) e as «épocas de resultados», os períodos em que as empresas cotadas divulgam os lucros do trimestre. Em cada um destes momentos o mercado ajusta as expectativas.'},
    {t:'h',id:'h3',x:'Medir a surpresa'},
    {t:'p',id:'p2a',x:'A conta é simples: <b>surpresa = valor real − previsão</b>. Quanto maior em módulo (e quanto mais importante o indicador), maior a reação esperada. Vê três exemplos inventados:'},
    {t:'cmp',id:'c3',head:['Indicador','Previsão','Real','Surpresa','Leitura habitual'],rows:[
      ['Inflação anual','2,8%','3,3%',_mer_pt(3.3-2.8,1)+' pp','Acima do esperado: pode aumentar a expectativa de taxas mais altas'],
      ['Crescimento do PIB (trimestre)','0,4%','0,1%',_mer_pt(0.1-0.4,1)+' pp','Abaixo do esperado: economia mais fraca; pode reforçar a expectativa de cortes de taxas'],
      ['Taxa de desemprego','6,5%','6,5%',_mer_pt(0,1)+' pp','Em linha: pouca reação, o mercado já contava com isto']],
      cap:'Valores inventados. «pp» = pontos percentuais. A leitura depende do contexto: o que importa é o que o mercado já tinha no preço.'},
    {t:'fazve',id:'q1',ensina:['p1','p2a','c3'],q:'Uma previsão apontava para uma inflação de 2,8% e saiu 3,3%. Qual foi a surpresa, em pontos percentuais?',unit:'pp',answer:3.3-2.8,tol:.02,why:'3,3 − 2,8 = 0,5 pontos percentuais acima do esperado. É uma surpresa para cima, que costuma aumentar a expectativa de taxas de juro mais altas.'},
    {t:'decide',id:'q2',ensina:['p1','c3'],label:'Decide',q:'A inflação esperada era 2,8% e saiu 3,3%. Como é que isto costuma ser lido?',o:['Como irrelevante, porque a inflação é sempre parecida','Como uma boa notícia para quem tem créditos','Como uma surpresa para cima: pode aumentar a expectativa de taxas de juro mais altas'],c:2,why:'Inflação acima do esperado sugere que o banco central pode manter ou subir as taxas, o que costuma pesar nos mercados e nos créditos indexados.'},
    {t:'h',id:'h4',x:'O que acontece no mercado'},
    {t:'p',id:'p2',x:'Dados de impacto alto costumam fazer o preço dar um salto nos minutos a seguir, com spreads mais largos e oscilações bruscas. Quem investe a longo prazo não precisa de reagir a cada dado: serve para <b>contextualizar</b> o que vês, não para fazer apostas.'},
    {t:'p',id:'p2b',x:'Os instrumentos que reagem primeiro costumam ser as obrigações, o euro e os futuros dos índices; as ações individuais reagem logo a seguir. Um mesmo dado pode ter efeitos contrários: uma criação de emprego forte é boa para a economia, mas se levar o banco central a subir mais as taxas, os mercados podem cair. Nada disto é regra fixa: o que conta é o que o mercado já esperava.'},
    {t:'h',id:'h5',x:'Um caso real: o referendo do «Brexit», 2016'},
    {t:'p',id:'p3b',x:'A 23 de junho de 2016, o Reino Unido votou em referendo se saía da União Europeia. A maioria das sondagens e dos analistas apontava para a permanência. Quando os resultados mostraram a vitória da saída, durante a madrugada, a libra afundou-se numa das maiores quedas diárias de sempre e as bolsas europeias caíram com força no dia seguinte. Não foi o resultado em si que fez os mercados mexer, foi a <b>diferença entre o esperado e o que aconteceu</b>.'},
    {t:'p',id:'p3c',x:'O mesmo se vê nos dados do dia a dia, em ponto pequeno: um dado «mau» que já estava previsto passa quase despercebido; um dado «bom» mas abaixo do esperado pode fazer o mercado cair.'},
    {t:'h',id:'h6',x:'Os erros que mais custam'},
    {t:'ul',id:'u1',x:[
      'Reagir ao valor do dado e não à surpresa face à previsão.',
      'Ignorar o fuso horário do calendário e perder a hora do dado, ou confundir as horas.',
      'Dar uma ordem a mercado no minuto a seguir a um dado importante, quando os spreads estão mais largos.',
      'Tentar «apostar» no resultado do dado: os profissionais fazem isto com informação e rapidez que tu não tens.',
      'Sair da carteira de longo prazo por causa de um único dado negativo.']},
    {t:'erro',id:'q3',ensina:['p1','p2a','c3','p2'],label:'Encontra o erro',q:'Uma destas frases sobre o calendário económico está errada. Qual?',o:['A previsão é a média das estimativas dos analistas','A surpresa é a diferença entre o real e a previsão','Um dado «mau» que já estava totalmente previsto deve fazer o mercado cair muito','Quem investe a longo prazo não precisa de reagir a cada dado'],c:2,why:'Se o dado já estava no preço, não há surpresa, e o mercado reage pouco. O que mexe com o preço é o que não estava previsto.'},
    {t:'decide',id:'q4',ensina:['p2'],label:'Decide',q:'Quem investe a longo prazo, com compras regulares, precisa de reagir a cada dado do calendário?',o:['Não: o calendário serve sobretudo para dar contexto às oscilações','Sim, para não perder dinheiro'],c:0,why:'O curto prazo é ruído para quem investe a muitos anos. O calendário ajuda a perceber o que se passa, não a prever o mercado.'},
    {t:'h',id:'h7',x:'Em Portugal'},
    {t:'p',id:'p3',x:'Na vista <b>Calendário</b> deste site podes ver os eventos da semana, ordenados por hora e impacto.'},
    {t:'p',id:'p3d',x:'Um cuidado muito português: muitos calendários europeus e a Euronext indicam as horas em CET (hora da Europa Central), que é uma hora à frente da hora de Portugal continental. Uma decisão do BCE anunciada às 14:15 CET acontece, por isso, às 13:15 em Portugal continental. O INE, o Banco de Portugal, o Eurostat e o BCE publicam os calendários das suas divulgações com antecedência nos respetivos sites. Para os horários de negociação, vê o tema «Horários da Euronext Lisboa».'},
    {t:'fazve',id:'q5',ensina:['p3d'],q:'Um calendário indica uma divulgação às 10:00 CET. Que horas são em Portugal continental? Responde com a hora (formato 24 h, só o número da hora).',unit:'h',answer:9,tol:.01,why:'Portugal continental está uma hora atrás da hora da Europa Central (CET): 10:00 CET são 09:00 em Lisboa. Convém confirmar sempre o fuso horário que o calendário usa.'},
    {t:'h',id:'h8',x:'Em poucas palavras'},
    {t:'ul',id:'u2',x:[
      'Cada linha tem hora, país, indicador, previsão, valor anterior e valor real.',
      'A surpresa (real − previsão) é o que mexe com o preço, não o valor em si.',
      'Inflação, emprego, PIB, decisões de taxas e resultados de empresas são os eventos que mais pesam.',
      'Em torno dos dados importantes há oscilações e spreads mais largos: cuidado com ordens a mercado.',
      'Quem investe a longo prazo usa o calendário para dar contexto, não para fazer apostas; e confirma sempre o fuso horário.']}
  ], src:[
    {l:'BCE: Banco Central Europeu (calendários de reuniões e divulgações)',u:'https://www.ecb.europa.eu'},
    {l:'INE: calendário de divulgação',u:'https://www.ine.pt'}] }
);

// ---- A vida de uma ação (acrescentada em 17/11/2026) ----
const _ac_n=n=>Number(n).toLocaleString('pt-PT',{minimumFractionDigits:2,maximumFractionDigits:2})+' €';
// Preço teórico depois de um aumento de capital: n ações antigas a p, m novas a q
const _ac_terp=(n,p,m,q)=>(n*p+m*q)/(n+m);
const _ac_T=_ac_terp(4,10,1,8), _ac_D=10-_ac_T;
const _ac_cvm={l:'CMVM: Código dos Valores Mobiliários e regulamentação',u:'https://www.cmvm.pt/'};

LRN.push(
{ id:'vida-acao', topic:'mercados', o:2.5, title:'A vida de uma ação: IPO, aumentos de capital, splits, recompras e OPA', mins:9,
  lead:'Uma ação não fica igual para sempre. A empresa pode entrar em bolsa, pedir mais dinheiro aos acionistas, dividir as ações, recomprá-las ou ser comprada por outra. Cada um destes acontecimentos mexe no que tens, e alguns obrigam-te a decidir num prazo curto.',
  blocks:[
    {t:'h',id:'h0',x:'Uma imagem para perceber'},
    {t:'p',id:'p0',x:'Pensa na empresa como uma piza cortada em fatias. Cada ação é uma fatia. A empresa pode cortar a piza em mais fatias (split), fazer uma piza maior com dinheiro novo e cortar fatias novas (aumento de capital), comer algumas fatias de volta (recompra), ou alguém pode querer comprar a piza inteira (OPA). Em cada caso, a pergunta certa é sempre a mesma: <b>a minha parte da piza ficou maior, igual ou menor?</b>'},
    {t:'h',id:'h1',x:'Nascer em bolsa: a oferta pública inicial (IPO)'},
    {t:'p',id:'p1',x:'Uma empresa entra em bolsa com uma <b>oferta pública inicial</b> (em inglês, IPO). Vende ações novas, para se financiar, ou os donos antigos vendem parte das suas. É o <b>mercado primário</b>: compras diretamente à empresa ou aos vendedores, ao preço da oferta. Depois disso as ações passam a negociar entre investidores, no <b>mercado secundário</b>, que é a bolsa do dia a dia.'},
    {t:'ul',id:'u1',x:[
      '<b>Prospeto.</b> Antes de uma oferta pública é publicado um prospeto, aprovado pelo supervisor (em Portugal, a CMVM). Diz o que a empresa faz, quanto deve, os riscos e para que quer o dinheiro.',
      '<b>Intervalo de preço e procura.</b> Os bancos que montam a oferta recolhem ordens dos investidores e fixam o preço final dentro de um intervalo.',
      '<b>Rateio.</b> Se a procura for maior do que a oferta, cada um recebe só uma parte das ações que pediu.',
      '<b>Período de bloqueio (lock-up).</b> Os acionistas antigos ficam muitas vezes impedidos de vender durante uns meses. Quando o prazo acaba, pode haver mais oferta e pressão sobre o preço.']},
    {t:'p',id:'p2',x:'Um IPO é o momento em que quem vende sabe muito mais do que quem compra: os donos escolhem quando vender, e normalmente escolhem um momento bom para eles. Estudos académicos sobre milhares de IPOs, como os de Jay Ritter (Universidade da Florida), apontam que, em média, as ações acabadas de entrar em bolsa renderam menos do que empresas comparáveis nos anos seguintes. Em média não quer dizer sempre, mas a euforia do primeiro dia não é um bom motivo para comprar.'},
    {t:'note',id:'n1',x:'Um caso conhecido: o Facebook entrou em bolsa em maio de 2012 a 38 dólares por ação e, em poucos meses, chegou a valer menos de metade. Anos depois valia muitas vezes mais. Quem comprou no primeiro dia pela emoção teve de aguentar uma queda forte antes de ganhar alguma coisa.'},
    {t:'h',id:'h2',x:'Aumento de capital: quando a empresa pede mais dinheiro'},
    {t:'p',id:'p3',x:'Num <b>aumento de capital</b>, a empresa emite ações novas e vende-as, normalmente com desconto. Para proteger os acionistas que já existem, costuma dar-lhes <b>direitos de subscrição</b>: o direito de comprar as ações novas antes dos outros, em proporção do que já têm. Esses direitos têm valor e podem vender-se em bolsa durante um prazo curto.'},
    {t:'p',id:'p4',x:`Um exemplo com valores de exemplo. Tens 1 000 ações a 10 €. A empresa oferece 1 ação nova por cada 4 que tens, a 8 €. Depois da operação, o preço teórico fica em ${_ac_n(_ac_T)}: é a média ponderada de 4 ações a 10 € e 1 a 8 €. Cada direito (um por ação antiga) vale cerca de ${_ac_n(_ac_D)}. Tens três caminhos:`},
    {t:'cmp',id:'c1',head:['O que fazes','Dinheiro que pões ou recebes','Valor das tuas ações depois','Resultado'],rows:[
      ['Subscreves as 250 ações novas','Pões '+_ac_n(250*8),_ac_n(1250*_ac_T),'Ficas igual: o que pagaste está nas ações'],
      ['Vendes os direitos','Recebes '+_ac_n(1000*_ac_D),_ac_n(1000*_ac_T),'Ficas igual: o valor do direito compensa a descida'],
      ['Não fazes nada','Nada',_ac_n(1000*_ac_T),'Perdes '+_ac_n(1000*_ac_D)+', porque o direito expira sem valor']],
      cap:'Valores de exemplo, sem comissões nem impostos. O preço real depois do aumento depende do mercado.'},
    {t:'p',id:'p5',x:'O aumento de capital em si não te torna mais rico nem mais pobre: o desconto é compensado pelo valor do direito. O que te faz perder é <b>ignorar o prazo</b>. A outra questão é porque é que a empresa precisa do dinheiro: para crescer é uma coisa, para tapar perdas ou pagar dívida que não consegue pagar é outra. Em 2014, poucas semanas antes da resolução do BES, o banco tinha feito um aumento de capital de cerca de mil milhões de euros; quem subscreveu ficou com ações praticamente sem valor.'},
    {t:'h',id:'h3',x:'Split e agrupamento: mais fatias, a mesma piza'},
    {t:'p',id:'p6',x:'Num <b>split</b> (desdobramento), cada ação passa a valer várias, e o preço divide-se na mesma proporção. Tens 10 ações a 400 €? Com um split de 4 para 1 passas a ter 40 ações a 100 €. Continuas com 4 000 €. Nada muda no valor da empresa nem na tua parte. A Apple fez um split de 4 para 1 em 2020 e a Nvidia um de 10 para 1 em 2024. As empresas fazem-no porque um preço por ação mais baixo é mais fácil de negociar em lotes pequenos.'},
    {t:'p',id:'p7',x:'O contrário é o <b>agrupamento</b> (reverse split): várias ações juntam-se numa. Também não muda o valor, mas costuma acontecer em empresas cujo preço caiu muito e que querem sair de valores de cêntimos. Não é uma regra, mas é um sinal a investigar.'},
    {t:'h',id:'h4',x:'Recompra de ações: a empresa compra-se a si própria'},
    {t:'p',id:'p8',x:`Numa <b>recompra</b>, a empresa usa dinheiro para comprar as suas próprias ações em bolsa e, muitas vezes, anulá-las. Se uma empresa lucra 100 milhões de euros e tem 100 milhões de ações, o lucro por ação é 1 €. Se recomprar e anular 10% das ações, o mesmo lucro passa a dividir-se por 90 milhões: ${_ac_n(100/90)} por ação. A tua fatia da piza ficou maior sem fazeres nada.`},
    {t:'p',id:'p9',x:'A recompra é uma alternativa ao dividendo para devolver dinheiro aos acionistas. A diferença para ti, em Portugal: o dividendo é tributado quando o recebes; com a recompra só pagas imposto sobre a mais-valia quando venderes. Mas uma recompra só cria valor se a empresa comprar as ações abaixo do que valem. Comprar caro, só para fazer subir o lucro por ação, destrói dinheiro dos acionistas que ficam.'},
    {t:'h',id:'h5',x:'OPA: quando alguém quer comprar a empresa inteira'},
    {t:'p',id:'p10',x:'Uma <b>oferta pública de aquisição</b> (OPA) é uma proposta feita a todos os acionistas para lhes comprar as ações a um preço fixo, quase sempre acima do preço de bolsa. A essa diferença chama-se <b>prémio</b>. Podes aceitar (vendes ao preço da oferta) ou não aceitar (ficas com as ações). A OPA pode ser <b>voluntária</b> ou <b>obrigatória</b>: a lei obriga quem passa certos limiares de direitos de voto a oferecer-se para comprar as ações aos restantes, para que os pequenos acionistas possam sair ao mesmo preço.'},
    {t:'note',id:'n2',pending:true,x:'No Código dos Valores Mobiliários, a OPA obrigatória está no artigo 187.º, para quem ultrapassa um terço ou metade dos direitos de voto de uma sociedade aberta, e a aquisição potestativa (ficar com as ações dos restantes) está no artigo 194.º, a partir de 90%. Encontrámos estes números só em fontes secundárias. Confirma no texto consolidado do Código.'},
    {t:'p',id:'p11',x:'Se a OPA tiver sucesso e o comprador ficar com quase todas as ações, pode obrigar os restantes a vender (<b>aquisição potestativa</b>) e retirar a empresa da bolsa. Quem não aceitou acaba por vender na mesma, ou fica com ações difíceis de vender. Em Portugal houve casos marcantes: a OPA da Sonaecom sobre a Portugal Telecom falhou em 2007, e a OPA sobre a Brisa, em 2012, levou a empresa a sair da bolsa.'},
    {t:'h',id:'h6',x:'Tudo numa tabela'},
    {t:'cmp',id:'c2',head:['Acontecimento','Número de ações','Valor da tua posição no dia','Tens de decidir?'],rows:[
      ['IPO','Ações novas à venda','Só se comprares','Sim, se quiseres entrar'],
      ['Aumento de capital','Aumenta','Igual, se agires','Sim, dentro do prazo dos direitos'],
      ['Split ou agrupamento','Multiplica ou divide','Igual','Não'],
      ['Recompra','Diminui','Igual; a tua parte cresce','Não'],
      ['Dividendo em ações','Aumenta para todos','Igual','Às vezes, se houver escolha entre ações e dinheiro'],
      ['Cisão (spin-off)','Recebes ações de uma nova empresa','Igual, repartido por duas','Não, mas passas a ter duas posições'],
      ['OPA','Pode desaparecer da bolsa','Prémio, se aceitares','Sim, dentro do prazo da oferta']],
      cap:'Valores no próprio dia, antes de o mercado reagir à notícia.'},
    {t:'h',id:'h7',x:'Os erros que mais custam'},
    {t:'ul',id:'u2',x:[
      'Deixar expirar direitos de subscrição sem os usar nem vender.',
      'Achar que um split torna a ação «mais barata». Só muda o tamanho das fatias.',
      'Comprar num IPO pelo barulho, sem ler o prospeto.',
      'Não aceitar uma OPA que vai tirar a empresa da bolsa, à espera de um preço melhor que nunca chega.',
      'Comprar uma ação que caiu muito só porque fez um agrupamento e o preço «parece» normal.',
      'Ignorar as mensagens da corretora sobre eventos: muitas têm prazo e uma opção por omissão.']},
    {t:'h',id:'h8',x:'Em Portugal'},
    {t:'p',id:'p12',x:'As ofertas públicas em Portugal (IPO, aumentos de capital, OPA) têm prospeto aprovado pela CMVM e publicado no seu site, no sistema de difusão de informação, junto com os anúncios da empresa. A corretora ou o banco avisam-te dos eventos que afetam as tuas ações e dizem-te o prazo e o que acontece se não responderes. Se usas uma corretora estrangeira, pergunta como trata os direitos de subscrição e as ofertas: nem todas deixam participar em todas as operações. Quanto a impostos, vender direitos ou aceitar uma OPA é uma venda: o ganho entra nas mais-valias.'},
    {t:'h',id:'h9',x:'Em poucas palavras'},
    {t:'ul',id:'u3',x:[
      'Pergunta sempre: a minha parte da empresa ficou maior, igual ou menor?',
      'IPO: quem vende sabe mais do que quem compra; lê o prospeto.',
      'Aumento de capital: subscreve ou vende os direitos; não fazer nada é perder.',
      'Split e agrupamento não mudam o valor; a recompra aumenta a tua parte.',
      'OPA: há prémio e prazo; se a empresa sair da bolsa, ficar de fora pode custar caro.']},
    {t:'fazve',id:'q1',ensina:['p4','c1'],q:'Uma ação vale 20 €. A empresa oferece 1 ação nova por cada 4, a 15 €. Qual é o preço teórico depois do aumento, em €?',unit:'€',answer:Number(_ac_terp(4,20,1,15).toFixed(2)),tol:.02,why:'(4 × 20 + 1 × 15) ÷ 5 = 95 ÷ 5 = 19 €.'},
    {t:'decide',id:'q2',ensina:['p5','c1'],label:'Decide',q:'A corretora avisa-te que tens direitos de subscrição que expiram amanhã, e não tens dinheiro para subscrever. O que fazes?',o:['Nada: sem dinheiro não há nada a fazer','Vendo os direitos em bolsa antes de expirarem','Vendo as ações todas'],c:1,why:'Os direitos têm valor. Vendê-los compensa a descida do preço da ação; se os deixares expirar, perdes esse valor.'},
    {t:'erro',id:'q3',ensina:['p6','p8','c2'],label:'Encontra o erro',q:'Uma destas frases está errada. Qual?',o:['Um split de 2 para 1 duplica o número de ações e divide o preço por dois','Uma recompra com anulação aumenta a tua parte da empresa','Depois de um split, a tua posição vale o dobro','Um agrupamento costuma acontecer em empresas cujo preço caiu muito'],c:2,why:'O split não muda o valor da posição: tens o dobro das ações a metade do preço.'},
    {t:'decide',id:'q4',ensina:['p10','p11'],label:'Decide',q:'Há uma OPA sobre uma empresa de que tens ações, com prémio de 20%, e o comprador diz que quer tirá-la da bolsa. O que pesas primeiro?',o:['Se acho que a empresa vale bem mais do que a oferta, sabendo que posso ficar com ações difíceis de vender','Nada: OPA é sempre para recusar','O preço a que comprei'],c:0,why:'O preço de compra não interessa ao mercado. A pergunta é se a oferta é justa face ao que a empresa vale e ao risco de ficares preso numa empresa fora da bolsa.'}
  ], src:[_CMVM,_ac_cvm,_AT_72] }
);
